(window.EX_CHUNKS=window.EX_CHUNKS||{})["b43"]={"包子":[["早餐我买了两个热腾腾的包子。","ئەتىگەنلىك تاماققا مەن ئىككى دانە قىزىق بولغان بوزى سېتىۋالدىم.","etigenlik tamaqqa men ikki dane qiziq bolghan bozi sétiwaldim."]],"牛仔裤":[["她穿着一条蓝色牛仔裤。","ئۇ كۆك رەڭلىك جىنسى كىيىم كىيىپتۇ.","u kök renglik jinsi kiyim kiyiptu."]],"劳驾":[["劳驾让一下，谢谢您的配合。","كەچۈرۈڭ، ئازراق يول بېرىڭ، ھەمكارلىقىڭىزغا رەھمەت.","kechürüng, azraq yol béring, hemkarliqingizgha rehmet."]],"穿越":[["这部电影讲述了一次惊心动魄的穿越之旅。","بۇ كىنو ھەيران قالارلىق بىر سەپەرنى سۆزلەيدۇ.","bu kino heyran qalarliq bir seperni sözleydu."]],"争气":[["他一定要争气，为家人争光。","ئۇ چوقۇم تىرىشىپ، ئائىلىسى ئۈچۈن ئابروي قازىنىشى كېرەك.","u choqum tiriship, ailisi üchün abroy qazinishi kérek."]],"哫":[["他哫哫地敲着桌子。","ئۇ دۇڭدۇڭلاپ ئۈستەلنى ئۇرماقتا.","u dungdunglap üstelni urmaqta."]],"懫":[["他表现出懫怒。","ئۇ ئاچچىقلىنىش ھالىتىنى كۆرسەتتى.","u achchiqlinish halitini körsetti."]],"棫":[["棫树适应性强。","يۈ دەرىخى مۇھىتقا ماسلىشىشچانلىقى كۈچلۈك.","yü derixi muhitqa maslishishchanliqi küchlük."]],"桫":[["桫椤是一种古老的蕨类植物。","سۇولۇڭ قەدىمىي بىر خىل پاپۇرتنىك ئۆسۈملۈك.","suolung qedimiy bir xil papurtnik ösümlük."]],"籫":[["籫竹的茎节很坚硬。","زۇەن بامبۇكىنىڭ بوغۇملىرى بەك قاتتىق.","zuen bambukining boghumliri bek qattiq."]],"芫":[["芫荽的香气非常浓郁。","يۈمغاق ئوتىنىڭ خۇش پۇرىقى ئىنتايىن كۈچلۈك.","yümghaq otining xush puriqi intayin küchlük."]],"蓫":[["蓫草的根系非常发达。","توققۇز تامانلىق ئوتنىڭ يىلتىز سىستېمىسى ئىنتايىن تەرەققىي قىلغان.","toqquz tamanliq otning yiltiz sistémisi intayin tereqqiy qilghan."]],"菫":[["紫菫是一种美丽的花卉。","كۈنچىقار بىر گۈزەل گۈلدۇر.","künchiqar bir güzel güldur."]],"趫":[["他趫健地跑完了全程。","ئۇ چاققانلىق بىلەن پۈتۈن مۇساپىنى يۈگۈرۈپ چىقتى.","u chaqqanliq bilen pütün musapini yügürüp chiqti."]],"闫":[["闫老师是我最喜欢的语文教师。","يەن ئوقۇتقۇچى مېنىڭ ئەڭ ياخشى كۆرىدىغان تىل-ئەدەبىيات ئوقۇتقۇچىم.","yen oqutquchi méning eng yaxshi köridighan til-edebiyat oqutquchim."]],"鬫":[["鬫火燃烧，照亮了整个夜空。","ئوت ئالقىنى يېنىپ، پۈتۈن ئاسماننى يورۇتتى.","ot alqini yénip, pütün asmanni yorutti."]],"一之为甚":[["一之为甚，不可再也。","بىر قېتىم قىلىشلا بەك ئېغىر، ئۇنى قايتا قىلغىلى بولمايدۇ.","bir qétim qilishla bek éghir, uni qayta qilghili bolmaydu."]],"一决雌雄":[["这场比赛将一决雌雄。","بۇ مۇسابىقە غالىبنى ئېنىقلايدۇ.","bu musabiqe ghalibni éniqlaydu."]],"三星乡":[["三星乡是某个县的一个乡镇。","سەنسىڭ يېزىسى مەلۇم بىر ناھىيەنىڭ بىر يېزىسى.","sensing yézisi melum bir nahiyening bir yézisi."]],"七美":[["七美姐妹的舞蹈令人惊艳。","يەتتە گۈزەل ئاچا-سىڭىلنىڭ ئۇسسۇلى كىشىنى ھەيران قالدۇرىدۇ.","yette güzel acha-singilning ussuli kishini heyran qalduridu."]],"三十六字母":[["古代汉语有三十六字母的发音系统。","قەدىمكى خەنزۇ تىلىدا ئوتتۇز ئالتە ھەرپلىك تەلەپپۇز سىستېمىسى بار.","qedimki xenzu tilida ottuz alte herplik teleppuz sistémisi bar."]],"三个臭皮匠，合成一个诸葛亮":[["三个臭皮匠，合成一个诸葛亮，说明集思广益的重要性。","ئۈچ دانا كونا كۆنچى بىرلىكتە بىر جوگېلىاڭ بولىدۇ، بۇ كۆپچىلىك ئەقلىنى جەم قىلىشنىڭ مۇھىملىقىنى چۈشەندۈرىدۇ.","üch dana kona könchi birlikte bir jogéliang bolidu, bu köpchilik eqlini jem qilishning muhimliqini chüshendüridu."]],"三都县":[["三都县风景优美。","ئۈچ دۇ ناھىيىسىنىڭ مەنزىرىسى گۈزەل.","üch du nahiyisining menzirisi güzel."]],"上上之策":[["这是上上之策。","بۇ ئەڭ ياخشى ئىستراتېگىيە.","bu eng yaxshi istratégiye."]],"三角柱体":[["三角柱体有六个面。","ئۈچبۇلۇڭلۇق تۈۋرۈك جىسىمنىڭ ئالتە يۈزى بار.","üchbulungluq tüwrük jisimning alte yüzi bar."]],"不同凡响":[["他的成就不同凡响。","ئۇنىڭ نەتىجىسى ئادەتتىن تاشقىرى.","uning netijisi adettin tashqiri."]],"下辖":[["该省下辖多个城市。","بۇ ئۆلكىنىڭ ئاستىدا بىر قانچە شەھەر بار.","bu ölkining astida bir qanche sheher bar."]],"不幸之事":[["那场火灾是不幸之事。","ئۇ ئوت ئاپىتى تەلەيسىزلىك ئىشى ئىدى.","u ot apiti teleysizlik ishi idi."]],"不拘":[["他为人不拘小节。","ئۇ كىچىك ئىشلارغا پەرۋا قىلمايدۇ.","u kichik ishlargha perwa qilmaydu."]],"不在了":[["他早已不在了，离开了我们。","ئۇ ئاللىبۇرۇن يوق، بىزدىن ئايرىلدى.","u alliburun yoq, bizdin ayrildi."]],"不香吗":[["这菜味道不香吗？","بۇ تاماقنىڭ تەمى خۇش ئەمەسما؟","bu tamaqning temi xush emesma?"]],"不说自明":[["这个道理不说自明，无需多言。","بۇ مەنتىق ئۆزىدىن ئېنىق، ئارتۇقچە سۆزلەشنىڭ ھاجىتى يوق.","bu mentiq özidin éniq, artuqche sözleshning hajiti yoq."]],"世态":[["世态的变迁让人感慨万千。","دۇنيا ھالىتىنىڭ ئۆزگىرىشى كىشىنى ھەسرەتكە سالىدۇ.","dunya halitining özgirishi kishini hesretke salidu."]],"不为酒困":[["他从不为酒困。","ئۇ ھەرگىز ھاراققا بېقىنىپ قالمايدۇ.","u hergiz haraqqa béqinip qalmaydu."]],"不甘":[["他不甘心失败。","ئۇ مەغلۇبىيەتكە قانائەت قىلمايدۇ.","u meghlubiyetke qanaet qilmaydu."]],"不畏强权":[["他从不畏强权。","ئۇ ھەرگىز كۈچلۈك ھوقۇقتىن قورقمايدۇ.","u hergiz küchlük hoquqtin qorqmaydu."]],"不题":[["这件事暂且不题，以后再详谈。","بۇ ئىشنى ھازىرچە تىلغا ئالمىدىم، كېيىن تەپسىلىي سۆزلىشىمىز.","bu ishni hazirche tilgha almidim, kéyin tepsiliy sözlishimiz."]],"并条":[["工人正在并条棉线。","ئىشچىلار پاختا يىپنى تەڭلەشتۈرۈۋاتىدۇ.","ishchilar paxta yipni tengleshtürüwatidu."]],"中前卫":[["中前卫是足球场上的关键位置。","جەڭ ئوتتۇرىسىدىكى ئارقا بەل ھەل قىلغۇچ ئورۇن.","jeng otturisidiki arqa bel hel qilghuch orun."]],"中游":[["河流中游地区地形平缓。","دەريانىڭ ئوتتۇرا ئېقىن رايونىنىڭ يەر شەكلى تۈزلەڭدۇر.","deryaning ottura éqin rayonining yer shekli tüzlengdur."]],"中间神经元":[["中间神经元传递神经信号。","ئوتتۇرا نېيرون نېير سىگنالىنى يەتكۈزىدۇ.","ottura néyron néyr signalini yetküzidu."]],"中关村":[["中关村是中国著名的科技园区。","جۇڭگوەنچۈن جۇڭگونىڭ مەشھۇر پەن-تېخنىكا رايونى.","junggoenchün junggoning meshhur pen-téxnika rayoni."]],"主祷文":[["主祷文是基督教的核心经文。","باش دۇئا خىرىستىيان دىنىنىڭ يادرولۇق تەلىمى.","bash dua xiristiyan dinining yadroluq telimi."]],"中常":[["中常会负责处理日常政务事务。","جۇڭچاڭخۇي كۈندىلىك ھۆكۈمەت ئىشلىرىغا بىر تەرەپ قىلىشقا مەسئۇلدۇر.","jungchangxuy kündilik hökümet ishlirigha bir terep qilishqa mes'uldur."]],"中庸":[["他主张处事应遵循中庸之道。","ئۇ ئىش بىجىرىشتە ئوتتۇرا يول تۇتۇش پرىنسىپىغا ئەمەل قىلىشنى تەشەببۇس قىلىدۇ.","u ish bijirishte ottura yol tutush prinsipigha emel qilishni teshebbus qilidu."]],"九寨沟县":[["九寨沟县拥有丰富的自然资源。","جۇجايقو ناھىيىسى مول تەبىئىي بايلىققا ئىگە.","jujayqo nahiyisi mol tebiiy bayliqqa ige."]],"乙氨基":[["乙氨基常用于合成各种药物分子。","بىڭئامىنو گۇرۇپپىسى كۆپ خىل دورا مولېكۇلىلىرىنى سىنتېزلاشتا كۆپ ئىشلىتىلىدۇ.","bing'amino guruppisi köp xil dora molékulilirini sintézlashta köp ishlitilidu."]],"干贝":[["干贝是海鲜中常见的干货，味道鲜美。","قۇرۇق دېڭىز مەھسۇلاتى دېڭىز تائاملىرى ئىچىدە كۆپ ئۇچرايدىغان قۇرۇق يېمەكلىكتۇر، تەمى لەززەتلىك.","quruq déngiz mehsulati déngiz taamliri ichide köp uchraydighan quruq yémekliktur, temi lezzetlik."]],"于丹":[["于丹是一位著名学者。","يۈ دەن تونۇلغان ئالىمدۇر.","yü den tonulghan alimdur."]],"五代十国":[["五代十国是分裂割据的时代。","بەش سۇلالە ئون پادىشاھلىق پارچىلىنىپ ئۆز ئالدىغا ھۆكۈمرانلىق قىلغان دەۋردۇر.","besh sulale on padishahliq parchilinip öz aldigha hökümranliq qilghan dewrdur."]],"亚洲漠地林莺":[["亚洲漠地林莺是一种候鸟。","ئاسىيا چۆل توڭگۇزى بىر كۆچمەن قۇش.","asiya chöl tongguzi bir köchmen qush."]],"亚原子":[["亚原子粒子在量子力学中很重要。","ئاتوم ئاستى زەررىچىلىرى كۋانت مېخانىكىسىدا مۇھىمدۇر.","atom asti zerrichiliri kwant méxanikisida muhimdur."]],"交换代数":[["交换代数是数学的一个分支。","ئالماشتۇرۇش ئالگېبراسى ماتېماتىكىنىڭ بىر تارمىقى.","almashturush algébrasi matématikining bir tarmiqi."]],"交通卡":[["交通卡用于记录车辆通行信息。","قاتناش كارتىسى ئاپتوموبىلنىڭ يول يۈرۈش ئۇچۇرىنى خاتىرىلەشكە ئىشلىتىلىدۇ.","qatnash kartisi aptomobilning yol yürüsh uchurini xatirileshke ishlitilidu."]],"人无远虑，必有近忧":[["人无远虑，必有近忧，古人言得对。","ئادەم يىراقنى ئويلاپ باقمىسا، چوقۇم يېقىن كۈندىكى غەم-قايغۇغا يولۇقىدۇ، قەدىمكىلەر توغرا ئېيتقان.","adem yiraqni oylap baqmisa, choqum yéqin kündiki ghem-qayghugha yoluqidu, qedimkiler toghra éytqan."]],"京都府":[["京都府位于日本中部，以丰富的文化遗产闻名。","جىڭدوفۇ ياپونىيەنىڭ ئوتتۇرا قىسمىدا جايلاشقان بولۇپ، مول مەدەنىيەت مىراسلىرى بىلەن تونۇلغان.","jingdofu yaponiyening ottura qismida jaylashqan bolup, mol medeniyet mirasliri bilen tonulghan."]],"仁和":[["仁和是一个宁静的小镇。","جېنخې جىمجىت بىر كىچىك بازىرىدۇر.","jénxé jimjit bir kichik baziridur."]],"什么时候":[["什么时候开始这个新项目？","بۇ يېڭى تۈر قاچان باشلىنىدۇ؟","bu yéngi tür qachan bashlinidu?"]],"人口调查":[["政府定期进行人口调查以制定政策。","ھۆكۈمەت سىياسەت تۈزۈش ئۈچۈن مۇنتىزىم نۇپۇس تەكشۈرۈش ئېلىپ بارىدۇ.","hökümet siyaset tüzüsh üchün muntizim nupus tekshürüsh élip baridu."]],"仂语":[["这种仂语在少数民族中流传广泛。","بۇ خىل لېكسىكىلىق بىرلىك ئاز سانلىق مىللەتلەر ئارىسىدا كەڭ تارقالغان.","bu xil léksikiliq birlik az sanliq milletler arisida keng tarqalghan."]],"他迁":[["他迁指的是居民因各种原因迁移。","ئۇنىڭ كۆچۈشى ئاھالىلەرنىڭ تۈرلۈك سەۋەبلەر تۈپەيلىدىن كۆچۈشىنى كۆرسىتىدۇ.","uning köchüshi ahalilerning türlük sewebler tüpeylidin köchüshini körsitidu."]],"以貌取人":[["不能以貌取人，要深入了解他人。","تاشقى كۆرۈنۈشكە قاراپ كىشىنى باھالىغىلى بولمايدۇ، باشقىلارنى چوڭقۇر چۈشىنىش كېرەك.","tashqi körünüshke qarap kishini bahalighili bolmaydu, bashqilarni chongqur chüshinish kérek."]],"以身许国":[["她以身许国，守护国家安宁。","ئۇ ئۆزىنى دۆلەتكە بېغىشلاپ، دۆلەت تىنچلىقىنى قوغدىدى.","u özini döletke béghishlap, dölet tinchliqini qoghdidi."]],"以马内利":[["以马内利是基督教的重要教义。","ئىممانۇئېل خىرىستىيان دىنىنىڭ مۇھىم ئەقىدىسىدۇر.","immanuél xiristiyan dinining muhim eqidisidur."]],"仰望":[["孩子们仰望着星空，充满好奇。","بالىلار يۇلتۇزلۇق ئاسمانغا قاراپ، قىزىقىش بىلەن تولۇپ تاشتى.","balilar yultuzluq asmangha qarap, qiziqish bilen tolup tashti."]],"伊莱克斯":[["伊莱克斯是游戏里的英雄。","ئېلېكس ئويۇندىكى قەھرىمان.","éléks oyundiki qehriman."]],"伏尔泰":[["伏尔泰是法国著名的启蒙思想家。","ۋولتېر فرانسىيەدىكى مەشھۇر مەرىپەتپەرۋەر مۇتەپەككۇر.","woltér fransiyediki meshhur meripetperwer mutepekkur."]],"位元币":[["这种位元币的汇率每天都在波动。","بۇ خىل بىتكويننىڭ پۇل ئالماشتۇرۇش نىسبىتى ھەر كۈنى ئۆزگىرىپ تۇرىدۇ.","bu xil bitkoynning pul almashturush nisbiti her küni özgirip turidu."]],"住脚":[["他们决定不再住脚，继续前行。","ئۇلار ئەمدى توختاپ قالماسلىقنى، ئالدىغا ئىلگىرىلەشنى قارار قىلدى.","ular emdi toxtap qalmasliqni, aldigha ilgirileshni qarar qildi."]],"佛学":[["佛学研究的是佛教的哲学与教义。","بۇددا تەتقىقاتى بۇددا دىنىنىڭ پەلسەپىسى ۋە تەلىماتلىرىنى ئۆگىنىدۇ.","budda tetqiqati budda dinining pelsepisi we telimatlirini öginidu."]],"佐丹奴":[["佐丹奴是一家知名的日本鞋类品牌。","گيوردانو تونۇلغان ياپونىيە ئاياق كىيىم ماركىسى.","gyordano tonulghan yaponiye ayaq kiyim markisi."]],"佟佳江":[["佟佳江是清朝著名的将领。","تۇڭجيا جياڭ چىڭ سۇلالىسىنىڭ مەشھۇر سەركەردىسى.","tungjya jyang ching sulalisining meshhur serkerdisi."]],"低领口":[["这件衣服的低领口设计很时尚。","بۇ كىيىمنىڭ تۆۋەن ياقىلىق لايىھىسى بەك مودا.","bu kiyimning töwen yaqiliq layihisi bek moda."]],"佛书":[["《金刚经》是著名的佛教经典佛书。","«ئالتۇن نۇرلۇق سۇترا» داڭلىق بۇددا دىنى كلاسسىك بۇددا كىتابىدۇر.","«altun nurluq sutra» dangliq budda dini klassik budda kitabidur."]],"佤族":[["佤族是中国的一个少数民族。","ۋا مىللىتى جۇڭگونىڭ ئاز سانلىق مىللەتلىرىنىڭ بىرى.","wa milliti junggoning az sanliq milletlirining biri."]],"佩戴":[["她佩戴着珍珠耳环。","ئۇ مەرۋايىت زىرە تاقىۋالغان.","u merwayit zire taqiwalghan."]],"佩皮尼昂":[["佩皮尼昂是法国南部的一个城市。","پېرپىنيان فرانسىيەنىڭ جەنۇبىدىكى بىر شەھەر.","pérpinyan fransiyening jenubidiki bir sheher."]],"保护色":[["这种昆虫拥有与环境融为一体的保护色。","بۇ خىل ھاشارات مۇھىت بىلەن بىرلىشىپ كەتكەن قوغداش رەڭگىگە ئىگە.","bu xil hasharat muhit bilen birliship ketken qoghdash renggige ige."]],"保险套":[["使用保险套可以降低性病的传播风险。","سۇغۇرتا قالپىقىنى ئىشلىتىش جىنسىي كېسەللىكلەرنىڭ تارقىلىش خەۋپىنى تۆۋەنلىتەلەيدۇ.","sughurta qalpiqini ishlitish jinsiy késelliklerning tarqilish xewpini töwenliteleydu."]],"个展":[["这次个展备受期待。","بۇ قېتىمقى شەخسىي كۆرگەزمە ئىنتايىن كۈتۈلمەكتە.","bu qétimqi shexsiy körgezme intayin kütülmekte."]],"倒槽":[["水渠出现倒槽现象，需要立即修复。","سۇ ئېرىقىدا تەتۈر ئېقىن ھادىسىسى كۆرۈلۈپ، دەرھال رېمونت قىلىش كېرەك.","su ériqida tetür éqin hadisisi körülüp, derhal rémont qilish kérek."]],"修饰语":[["修饰语用来增强句子的表现力。","بېزەك سۆزلەر جۈملىنىڭ ئىپادىلەش كۈچىنى كۈچەيتىشكە ئىشلىتىلىدۇ.","bézek sözler jümlining ipadilesh küchini kücheytishke ishlitilidu."]],"偏置电流":[["电路中的偏置电流很稳定。","توك يولىدىكى ئېغىش توكى بەك مۇقىم.","tok yolidiki éghish toki bek muqim."]],"停靠港":[["货轮在停靠港装卸货物。","يۈك كېمىسى توختىتىش پورتىدا يۈك ئارتىپ چۈشۈردى.","yük kémisi toxtitish portida yük artip chüshürdi."]],"值得一提":[["这件事值得一提。","بۇ ئىش تىلغا ئېلىشقا ئەرزىيدۇ.","bu ish tilgha élishqa erziydu."]],"傈僳":[["傈僳族生活在云南的高山地区。","لىسۇ مىللىتى يۈننەننىڭ ئېگىز تاغلىق رايونلىرىدا ياشايدۇ.","lisu milliti yünnenning égiz taghliq rayonlirida yashaydu."]],"备荒":[["村庄积极备荒，确保粮食安全。","كەنت ئاچارچىلىققا قارشى تەييارلىقنى ئاكتىپ ئېلىپ بېرىپ، ئاشلىق بىخەتەرلىكىنى كاپالەتكە ئىگە قىلدى.","kent acharchiliqqa qarshi teyyarliqni aktip élip bérip, ashliq bixeterlikini kapaletke ige qildi."]],"伤透":[["他的心被彻底伤透了。","ئۇنىڭ كۆڭلى پۈتۈنلەي ئاغرىتىلدى.","uning köngli pütünley aghritildi."]],"储蓄率":[["国家鼓励提高个人储蓄率。","دۆلەت شەخسىي ئامانەت نىسبىتىنى ئۆستۈرۈشنى رىغبەتلەندۈرىدۇ.","dölet shexsiy amanet nisbitini östürüshni righbetlendüridu."]],"兀鹫":[["兀鹫是草原上的顶级掠食者。","ئۇدۇر تالا-يايلاقتىكى ئەڭ ئۈستۈن يىرتقۇچتۇر.","udur tala-yaylaqtiki eng üstün yirtquchtur."]],"光气":[["光气是一种有毒的化学物质。","فوسگېن بىر خىل زەھەرلىك خىمىيىلىك ماددىدۇر.","fosgén bir xil zeherlik ximiyilik maddidur."]],"光泽县":[["光泽县以盛产茶叶而闻名。","گۇاڭزې ناھىيىسى چاي ئىشلەپچىقىرىش بىلەن داڭلىق.","guangzé nahiyisi chay ishlepchiqirish bilen dangliq."]],"先决":[["这是解决问题的先决条件。","بۇ مەسىلىنى ھەل قىلىشنىڭ ئالدىنقى شەرتى.","bu mesilini hel qilishning aldinqi sherti."]],"先河":[["此举开创了行业先河。","بۇ ھەرىكەت ساھەدە ئالدىنقى ئۈلگىنى ياراتتى.","bu heriket sahede aldinqi ülgini yaratti."]],"入声":[["这个词属于入声调。","بۇ سۆز كىرىش ئاھەنگى ئەزاسىغا تەۋە.","bu söz kirish ahengi ezasigha tewe."]],"光笔":[["光笔可以用来在屏幕上书写。","نۇر قەلەم ئېكران ئۈستىدە يېزىشقا ئىشلىتىلىدۇ.","nur qelem ékran üstide yézishqa ishlitilidu."]],"两虎相斗，必有一伤":[["两虎相斗，必有一伤，这是自然法则。","ئىككى يولۋاس ئېلىشسا، چوقۇم بىرىسى يارىلىنىدۇ، بۇ تەبىئىي قانۇن.","ikki yolwas élishsa, choqum birisi yarilinidu, bu tebiiy qanun."]],"公斗":[["古代公斗是公开辩论的重要形式。","قەدىمكى ئاممىۋى مۇنازىرە ئوچۇق مۇنازىرىنىڭ مۇھىم شەكلى ئىدى.","qedimki ammiwi munazire ochuq munazirining muhim shekli idi."]],"公民权利":[["公民权利受法律保护，不可侵犯。","پۇقرالىق ھوقۇقى قانۇن تەرىپىدىن قوغدىلىدۇ، دەخلى قىلىشقا بولمايدۇ.","puqraliq hoquqi qanun teripidin qoghdilidu, dexli qilishqa bolmaydu."]],"公益活动":[["今天的公益活动帮助了贫困儿童。","بۈگۈنكى ئاممىۋى مەنپەئەت پائالىيىتى نامرات بالىلارغا ياردەم بەردى.","bügünki ammiwi menpeet paaliyiti namrat balilargha yardem berdi."]],"共享计划":[["这个共享计划得到了大家支持。","بۇ ئورتاق پىلان ئەھلى تەرىپىدىن قوللاندى.","bu ortaq pilan ehli teripidin qollandi."]],"凌夷":[["国家逐渐走向凌夷。","دۆلەت تەدرىجىي ئەڭگىشىشكە يۈزلەندى.","dölet tedrijiy enggishishke yüzlendi."]],"凌海":[["凌海是一个美丽的海滨城市。","لىڭخەي گۈزەل بىر دېڭىز بويى شەھىرى.","lingxey güzel bir déngiz boyi shehiri."]],"出生地":[["他的出生地在中国。","ئۇنىڭ تۇغۇلغان يېرى جۇڭگودا.","uning tughulghan yéri junggoda."]],"冬青树":[["冬青树常被用作节日装饰。","قىشلىق يېشىل دەرەخ كۆپىنچە بايرام بېزىكى سۈپىتىدە ئىشلىتىلىدۇ.","qishliq yéshil derex köpinche bayram béziki süpitide ishlitilidu."]],"冶荡":[["他的冶荡举止令人难以接受。","ئۇنىڭ بىھايالىق قىلمىشلىرىنى قوبۇل قىلىش قىيىن.","uning bihayaliq qilmishlirini qobul qilish qiyin."]],"冶金学":[["冶金学是材料科学的重要分支。","مېتاللورگىيە ماتېرىيالشۇناسلىقنىڭ مۇھىم تارمىقىدۇر.","métallorgiye matériyalshunasliqning muhim tarmiqidur."]],"冰岛":[["冰岛以极光和火山闻名。","ئىسلاندىيە شىمالىي چاقماق ۋە يانار تاغ بىلەن داڭلىق.","islandiye shimaliy chaqmaq we yanar tagh bilen dangliq."]],"出口调查":[["我们需要进行出口调查。","بىز ئېكسپورت تەكشۈرۈشى ئېلىپ بېرىشىمىز كېرەك.","biz éksport tekshürüshi élip bérishimiz kérek."]],"制服呢":[["他的制服呢？","ئۇنىڭ فورمىسى قېنى؟","uning formisi qéni?"]],"前尘":[["前尘往事已如烟。","ئالدىنقى دۇنيادىكى ئىشلار تۇتۇتتەك كېتىپتۇ.","aldinqi dunyadiki ishlar tututtek kétiptu."]],"刘家辉":[["刘家辉是著名的演员。","لىۇ جياخۇي مەشھۇر ئارتىس.","liu jyaxuy meshhur artis."]],"加里宁格勒":[["加里宁格勒是俄罗斯的一个城市。","كالىنىنگراد رۇسىيەنىڭ بىر شەھىرىدۇر.","kaliningrad rusiyening bir shehiridur."]],"加压":[["工程师对管道进行了加压测试。","ئىنژېنېر تۇرۇبا يولىغا بېسىم سىناق قىلدى.","inzhénér turuba yoligha bésim sinaq qildi."]],"胜率":[["他的胜率很高。","ئۇنىڭ غەلىبە نىسبىتى ناھايىتى يۇقىرى.","uning ghelibe nisbiti nahayiti yuqiri."]],"胜过":[["这个方案胜过其他方案。","بۇ پىلان باشقا پىلانلاردىن ئۈستۈن.","bu pilan bashqa pilanlardin üstün."]],"功罪":[["功罪难两全。","تۆھپە بىلەن جىنايەتنى ئىككىسىنى تەڭ قىلىش قىيىن.","töhpe bilen jinayetni ikkisini teng qilish qiyin."]],"功高望重":[["他功高望重，备受尊敬。","ئۇ تۆھپىسى يۇقىرى ۋە ئابرۇيى چوڭ بولۇپ، كۆپ ھۆرمەتكە سازاۋەر.","u töhpisi yuqiri we abruyi chong bolup, köp hörmetke sazawer."]],"加之":[["加之资源有限，进展缓慢。","ئۇنىڭ ئۈستىگە بايلىق چەكلىك بولغاچقا، تەرەققىيات ئاستا بولدى.","uning üstige bayliq cheklik bolghachqa, tereqqiyat asta boldi."]],"劝动":[["他成功劝动了朋友一起旅行。","ئۇ دوستىنى بىرلىكتە سەپەرگە چىقىشقا ئۇتۇقلۇق رىغبەتلەندۈردى.","u dostini birlikte seperge chiqishqa utuqluq righbetlendürdi."]],"化学系":[["他大学时就读于化学系。","ئۇ ئۇنىۋېرسىتېتتا ئوقۇغان چېغىدا خىمىيە فاكۇلتېتىدا ئوقۇغان.","u uniwérsitétta oqughan chéghida ximiye fakultétida oqughan."]],"汇划":[["银行通过汇划系统转账。","بانكا پۇل يۆتكەش سىستېمىسى ئارقىلىق ھېسابات يۆتكەيدۇ.","banka pul yötkesh sistémisi arqiliq hésabat yötkeydu."]],"半人马座":[["半人马座是南天星座之一。","كېنتاۋر يۇلتۇز تۈركۈمى جەنۇبىي ئاسمان يۇلتۇز تۈركۈملىرىنىڭ بىرىدۇر.","kéntawr yultuz türkümi jenubiy asman yultuz türkümlirining biridur."]],"北面":[["北面是房屋朝向的主要方向。","شىمال تەرەپ ئۆي يۈزلىنىشىنىڭ ئاساسلىق يۆنىلىشى.","shimal terep öy yüzlinishining asasliq yönilishi."]],"南面":[["南面阳光充足，气候温暖。","جەنۇب تەرەپتە قۇياش نۇرى مول، ھاۋاسى ئىللىق.","jenub terepte quyash nuri mol, hawasi illiq."]],"北寒带":[["北寒带是地球最寒冷的地区之一。","شىمالىي سوغۇق بەلباغ يەر شارىنىڭ ئەڭ سوغۇق رايونلىرىنىڭ بىرىدۇر.","shimaliy soghuq belbagh yer sharining eng soghuq rayonlirining biridur."]],"博雅":[["他博雅多才，才华横溢。","ئۇ كەڭ بىلىملىك ۋە ئىقتىدارلىق، تالانتى ئاشقان.","u keng bilimlik we iqtidarliq, talanti ashqan."]],"博鳌亚洲论坛":[["博鳌亚洲论坛每年举行一次。","بوئاۋ ئاسىيا مۇنبىرى ھەر يىلى بىر قېتىم ئۆتكۈزۈلىدۇ.","boaw asiya munbiri her yili bir qétim ötküzülidu."]],"南西诸岛":[["南西诸岛是重要的旅游胜地。","جەنۇبىي غەربىي ئاراللار مۇھىم ساياھەت جايى.","jenubiy gherbiy arallar muhim sayahet jayi."]],"卡侬":[["这款卡侬相机性能出色。","بۇ كانون فوتو ئاپپاراتىنىڭ ئىقتىدارى ئالاھىدە ياخشى.","bu kanon foto apparatining iqtidari alahide yaxshi."]],"厚待":[["他厚待每一位客人。","ئۇ ھەر بىر مېھمانغا قېلىن مۇئامىلە قىلىدۇ.","u her bir méhmangha qélin muamile qilidu."]],"卵黄腺":[["卵黄腺分泌卵黄物质。","تۇخۇم سېرىق بەزى تۇخۇم سېرىق ماددىسى ئاجرىتىدۇ.","tuxum sériq bezi tuxum sériq maddisi ajritidu."]],"卸责":[["他试图卸责，但无济于事。","ئۇ جاۋابكارلىقنى ئۈستىدىن تاشلاشقا ئۇرۇندى، ئەمما پايدىسى بولمىدى.","u jawabkarliqni üstidin tashlashqa urundi, emma paydisi bolmidi."]],"南征北战":[["南征北战形容征战四方。","جەنۇبقا يۈرۈش شىمالغا ئاتلىنىش تۆت تەرەپكە جەڭ قىلىشنى تەسۋىرلەيدۇ.","jenubqa yürüsh shimalgha atlinish töt terepke jeng qilishni teswirleydu."]],"口疮":[["他嘴里长了口疮。","ئۇنىڭ ئېغىزىدا يارا چىقتى.","uning éghizida yara chiqti."]],"口皮":[["他撕掉了嘴上的口皮。","ئۇ لەۋىدىكى ئېغىز تېرىسىنى يۇلۇپ تاشلىدى.","u lewidiki éghiz térisini yulup tashlidi."]],"取证":[["警察正在现场取证。","ساقچىلار نەق مەيداندا ئىسپات يىغماقتا.","saqchilar neq meydanda ispat yighmaqta."]],"只怕":[["只怕明天会下雨。","ئەتە يامغۇر ياغسا كېرەك.","ete yamghur yaghsa kérek."]],"古今小说":[["《古今小说》是明代的一部作品。","«قەدىمكى ۋە ھازىرقى رومانلار» مىڭ سۇلالىسى دەۋرىدىكى بىر ئەسەر.","«qedimki we hazirqi romanlar» ming sulalisi dewridiki bir eser."]],"台江区":[["台江区位于福州市中心地带。","تەيجياڭ رايونى فۇجۇ شەھىرىنىڭ مەركىزىي رايونىدا جايلاشقان.","teyjyang rayoni fuju shehirining merkiziy rayonida jaylashqan."]],"反腐倡廉":[["反腐倡廉是长期的重要任务。","چىرىكلىككە قارشى تۇرۇش ۋە پاكلىقنى تەشەببۇس قىلىش ئۇزۇن مۇددەتلىك مۇھىم ۋەزىپىدۇر.","chiriklikke qarshi turush we pakliqni teshebbus qilish uzun muddetlik muhim wezipidur."]],"吃人血馒头":[["他竟吃人血馒头，良心何在？","ئۇ ھەتتا ئادەم قېنى بىلەن پىشۇرۇلغان نان يېدى، ۋىجدانى قەيەردە؟","u hetta adem qéni bilen pishurulghan nan yédi, wijdani qeyerde?"]],"右倾":[["右倾政策不符合国家利益。","ئوڭچىل سىياسەت دۆلەت مەنپەئەتىگە ئۇيغۇن كەلمەيدۇ.","ongchil siyaset dölet menpeetige uyghun kelmeydu."]],"司法部":[["司法部管理全国司法行政事务。","ئەدلىيە مىنىستىرلىقى پۈتۈن مەملىكەتتىكى ئەدلىيە مەمۇرىي ئىشلىرىنى باشقۇرىدۇ.","edliye ministirliqi pütün memlikettiki edliye memuriy ishlirini bashquridu."]],"合阳":[["合阳是陕西的一个县。","خېيياڭ شەنشى ئۆلكىسىدىكى بىر ناھىيە.","xéyyang shenshi ölkisidiki bir nahiye."]],"合音":[["合音在音乐中很常见。","خېيىن مۇزىكىدا ئىنتايىن كۆپ ئۇچرايدۇ.","xéyin muzikida intayin köp uchraydu."]],"吉木萨尔":[["吉木萨尔是历史名城。","جىمۇسار تارىخىي مەشھۇر شەھەر.","jimusar tarixiy meshhur sheher."]],"同德":[["同德之人方能合作。","ئوخشاش ئەخلاقلىق كىشىلەرلا ھەمكارلىشالايدۇ.","oxshash exlaqliq kishilerla hemkarlishalaydu."]],"名优":[["这位名优的表演深入人心。","بۇ داڭلىق ئارتىسنىڭ ئويۇنى كىشىلەرنىڭ قەلبىگە چوڭقۇر سىڭدى.","bu dangliq artisning oyuni kishilerning qelbige chongqur singdi."]],"吴江":[["吴江是江苏省的一个地级市。","ۋۇجياڭ جياڭسۇ ئۆلكىسىنىڭ بىر ۋىلايەت دەرىجىلىك شەھىرى.","wujyang jyangsu ölkisining bir wilayet derijilik shehiri."]],"吴玉章":[["吴玉章是中国近代教育家。","ۋۇ يۈجياڭ جۇڭگونىڭ يېقىنقى زامان مائارىپچىسى.","wu yüjyang junggoning yéqinqi zaman maaripchisi."]],"周易":[["《周易》是中国古代经典。","«جۇيى» قەدىمكى جۇڭگونىڭ كلاسسىك ئەسىرى.","«juyi» qedimki junggoning klassik esiri."]],"吹熄":[["他吹熄了蜡烛，房间暗下来。","ئۇ شامنى پۈۋلەپ ئۆچۈردى، ئۆي قاراڭغۇلاشتى.","u shamni püwlep öchürdi, öy qarangghulashti."]],"周庄镇":[["周庄镇风景优美。","جوۋجۇاڭ بازىرىنىڭ مەنزىرىسى گۈزەل.","jowjuang bazirining menzirisi güzel."]],"哈巴狗":[["哈巴狗是一种小型犬。","خابا ئىتى بىر خىل كىچىك ئىت تۈرىدۇر.","xaba iti bir xil kichik it türidur."]],"告诵":[["他向长辈告诵自己的经历。","ئۇ چوڭلارغا ئۆز بېشىدىن ئۆتكەنلىرىنى سۆزلەپ بەردى.","u chonglargha öz béshidin ötkenlirini sözlep berdi."]],"品行":[["他的品行端正，是大家学习的榜样。","ئۇنىڭ ئەخلاق-پەزىلىتى دۇرۇس بولۇپ، ھەممىگە ئۈلگە.","uning exlaq-peziliti durus bolup, hemmige ülge."]],"品貌":[["他的品貌端庄，给人留下良好印象。","ئۇنىڭ چىرايى كېلىشكەن بولۇپ، كىشىلەرگە ياخشى تەسىر قالدۇرىدۇ.","uning chirayi kélishken bolup, kishilerge yaxshi tesir qalduridu."]],"咬字":[["说话时咬字不清会影响沟通效果。","سۆزلىگەندە تەلەپپۇزنىڭ ئېنىق بولماسلىقى ئالاقە ئۈنۈمىگە تەسىر كۆرسىتىدۇ.","sözligende teleppuzning éniq bolmasliqi alaqe ünümige tesir körsitidu."]],"唇角":[["唇角轻轻上扬，露出一丝微笑。","لەۋ بۇرجىكى ئاستا كۆتۈرۈلۈپ، سەل كۈلۈمسىرەش پەيدا بولدى.","lew burjiki asta kötürülüp, sel külümsiresh peyda boldi."]],"喇叭水仙":[["这种花叫喇叭水仙。","بۇ گۈل كەركىدان نەرگىسى دەپ ئاتىلىدۇ.","bu gül kerkidan nergisi dep atilidu."]],"喇叭花":[["喇叭花早晨会绽放。","كەركىدان گۈلى ئەتىگەندە ئېچىلىدۇ.","kerkidan güli etigende échilidu."]],"喜山红眉朱雀":[["另一种是喜山红眉朱雀。","يەنە بىر خىلى خۇشال تاغ قىزىل قاش قىزىلگۈمىدۇر.","yene bir xili xushal tagh qizil qash qizilgümidur."]],"乔治亚州":[["乔治亚州位于美国东南部。","جورجىيا شتاتى ئامېرىكىنىڭ جەنۇبىي شەرقىدە جايلاشقان.","jorjiya shtati amérikining jenubiy sherqide jaylashqan."]],"丧亲":[["他因丧亲而陷入深深的悲痛中。","ئۇ يېقىنلىرىدىن ئايرىلغانلىق ئۈچۈن چوڭقۇر قايغۇغا چۆمدى.","u yéqinliridin ayrilghanliq üchün chongqur qayghugha chömdi."]],"单传":[["家族中只有他一个男丁，是单传。","ئائىلىدە پەقەت ئۇلا بىر ئەر بالىسى، يەنى يەككە ئەۋلادتۇر.","ailide peqet ula bir er balisi, yeni yekke ewladtur."]],"单张":[["请出示单张门票。","يالغۇز بىر بېلەت كۆرسىتىڭ.","yalghuz bir bélet körsiting."]],"单杠":[["每天做单杠锻炼对身体有益。","ھەر كۈنى يالغۇز تۇرۇق مەشىق قىلىش بەدەنگە پايدىلىق.","her küni yalghuz turuq meshiq qilish bedenge paydiliq."]],"嘴损":[["他的嘴损，说话伤人。","ئۇنىڭ ئاغزى ئاچچىق، سۆزلىرى كىشىلەرنى ئاغرىتىدۇ.","uning aghzi achchiq, sözliri kishilerni aghritidu."]],"嘴甜心苦":[["她嘴甜心苦，内心充满委屈。","ئۇنىڭ ئاغزى تاتلىق، كۆڭلى ئاچچىق، ئىچىدە ئازاب-ئوقۇبەت تولغان.","uning aghzi tatliq, köngli achchiq, ichide azab-oqubet tolghan."]],"喷砂":[["喷砂工艺能去除锈迹。","قۇم پۈركۈش تېخنىكىسى زەڭنى يوقىتالايدۇ.","qum pürküsh téxnikisi zengni yoqitalaydu."]],"器官移殖":[["手术成功完成了器官移殖。","ئوپېراتسىيە مۇۋەپپەقىيەتلىك ئورۇندىلىپ ئورگان كۆچۈرۈش تاماملاندى.","opératsiye muweppeqiyetlik orundilip organ köchürüsh tamamlandi."]],"噶玛兰":[["噶玛兰是一种传统的乐器。","گامالان ئەنئەنىۋى بىر چالغۇ.","gamalan en'eniwi bir chalghu."]],"严以责己宽以待人":[["他严以责己宽以待人。","ئۇ ئۆزىگە قاتتىق، باشقىلارغا كەڭ قارايدۇ.","u özige qattiq, bashqilargha keng qaraydu."]],"四书":[["《四书》是儒家经典的重要著作。","«سىشۇ» كۇڭفۇزىيىلىك كلاسسىك ئەسەرلەرنىڭ مۇھىم ئەسىرى.","«sishu» kungfuziyilik klassik eserlerning muhim esiri."]],"四角形":[["四角形也叫四边形。","تۆت بۇلۇڭلۇق شەكىلنى تۆت تەرەپلىك دەپمۇ ئاتايدۇ.","töt bulungluq shekilni töt tereplik depmu ataydu."]],"国家主席":[["国家主席发表了重要讲话。","دۆلەت رەئىسى مۇھىم سۆز قىلدى.","dölet reisi muhim söz qildi."]],"国泰民安":[["国泰民安是人民的愿望。","دۆلەت ئامان، خەلق ئامان بولۇشى خەلقنىڭ ئارزۇسى.","dölet aman, xelq aman bolushi xelqning arzusi."]],"国姓乡":[["国姓乡以独特的文化闻名遐迩。","دۆلەت فامىلىلىك يېزا ئۆزىنىڭ ئالاھىدە مەدەنىيىتى بىلەن يىراق-يېقىنغا تونۇلغان.","dölet famililik yéza özining alahide medeniyiti bilen yiraq-yéqingha tonulghan."]],"图恩":[["图恩是一个美丽的村庄。","تۇن گۈزەل بىر كەنت.","tun güzel bir kent."]],"图样图森破":[["图样图森破，真有趣！","ئەندىزە ئىنتايىن قىزىقارلىق!","endize intayin qiziqarliq!"]],"圆拱":[["圆拱桥横跨了宽阔的河流。","يۇمىلاق كۆۋرۈك كەڭ دەريانى كېسىپ ئۆتتى.","yumilaq köwrük keng deryani késip ötti."]],"圆柱":[["圆柱是几何学中的基本图形。","يۇمىلاق تۈۋرۈك گېئومېتىرىيەدىكى ئاساسىي شەكىلدۇر.","yumilaq tüwrük géométiriyediki asasiy shekildur."]],"土耳其语":[["土耳其语属于突厥语系，语法较为复杂。","تۈرك تىلى تۈركىي تىل سىستېمىسىغا تەۋە، گرامماتىكىسى بىر قەدەر مۇرەككەپ.","türk tili türkiy til sistémisigha tewe, grammatikisi bir qeder murekkep."]],"地力":[["地力决定了作物产量。","يەر ئۈنۈمدارلىقى زىرائەت مەھسۇلات مىقدارىنى بەلگىلەيدۇ.","yer ünümdarliqi ziraet mehsulat miqdarini belgileydu."]],"国台办":[["国台办负责处理两岸事务。","دۆلەت تەيۋەن ئىشلىرى ئىشخانىسى ئىككى قىرغاق ئىشلىرىنى بىر تەرەپ قىلىشقا مەسئۇل.","dölet teywen ishliri ishxanisi ikki qirghaq ishlirini bir terep qilishqa mes'ul."]],"国富论":[["《国富论》是经济学经典著作。","«دۆلەت بېيىشى» ئىقتىسادشۇناسلىقتىكى كلاسسىك ئەسەردۇر.","«dölet béyishi» iqtisadshunasliqtiki klassik eserdur."]],"国师":[["国师在古代享有极高地位。","دۆلەت ئۇستازى قەدىمكى زاماندا ئىنتايىن يۇقىرى ئورۇنغا ئىگە ئىدى.","dölet ustazi qedimki zamanda intayin yuqiri orungha ige idi."]],"国新办":[["国新办定期发布权威新闻。","دۆلەت ئاخبارات ئىشخانىسى قەرەللىك ھالدا نوپۇزلۇق خەۋەرلەرنى ئېلان قىلىدۇ.","dölet axbarat ishxanisi qerellik halda nopuzluq xewerlerni élan qilidu."]],"地坛":[["地坛是古代祭祀的地方。","يەر ئىبادەتگاھى قەدىمدە قۇربانلىق قىلىدىغان جاي.","yer ibadetgahi qedimde qurbanliq qilidighan jay."]],"地理极":[["北极和南极是地球的地理极。","شىمالىي قۇتۇپ ۋە جەنۇبىي قۇتۇپ يەر شارىنىڭ جۇغراپىيەلىك قۇتۇپلىرىدۇر.","shimaliy qutup we jenubiy qutup yer sharining jughrapiyelik qutupliridur."]],"地震波":[["地震波是地震发生时向四周传播的震动。","زىلزىلە دولقۇنى زىلزىلە يۈز بەرگەندە تەرەپ-تەرەپكە تارقالىدىغان تەۋرىنىشتۇر.","zilzile dolquni zilzile yüz bergende terep-terepke tarqalidighan tewrinishtur."]],"垃圾车":[["垃圾车准时到达收集垃圾。","ئەخلەت ماشىنىسى ۋاقتىدا يېتىپ كېلىپ ئەخلەت يىغىدۇ.","exlet mashinisi waqtida yétip kélip exlet yighidu."]],"埋首":[["她埋首在书中，忘记了时间。","ئۇ كىتابقا باش قويۇپ، ۋاقىتنى ئۇنتۇپ قالدى.","u kitabqa bash qoyup, waqitni untup qaldi."]],"城根":[["城根下隐藏着古老的秘密。","شەھەر ئاساسى ئاستىدا قەدىمكى سىرلار يوشۇرۇنغان.","sheher asasi astida qedimki sirlar yoshurunghan."]],"地级市":[["地级市是中国的行政单位之一。","ۋىلايەت دەرىجىلىك شەھەر جۇڭگونىڭ مەمۇرىي بىرلىكلىرىنىڭ بىرى.","wilayet derijilik sheher junggoning memuriy birliklirining biri."]],"地藏王菩萨":[["地藏王菩萨以慈悲闻名。","دىزاڭ پادىشاھ بۇددا مېھرىبانلىقى بىلەن تونۇلغان.","dizang padishah budda méhribanliqi bilen tonulghan."]],"基肥":[["施用基肥有助于作物生长。","ئاساسىي ئوغۇت ئىشلىتىش زىرائەتلەرنىڭ ئۆسۈشىگە ياردەم قىلىدۇ.","asasiy oghut ishlitish ziraetlerning ösüshige yardem qilidu."]],"塑膜":[["塑膜用于包装产品。","پلاستىك پەردە مەھسۇلاتلارنى قاچىلاشقا ئىشلىتىلىدۇ.","plastik perde mehsulatlarni qachilashqa ishlitilidu."]],"塞擦音":[["塞擦音是语音学中的一个概念。","ئەففرىكاتىف ئاۋاز فىنېتىكا ئىلمىدىكى بىر ئۇقۇم.","effrikatif awaz finétika ilmidiki bir uqum."]],"塞翁失马安知非福":[["塞翁失马安知非福的道理深入人心。","سەئوڭ ئاتىنى يوقىتىپ ئات ساقلىغان بولسا بەختسىزلىك ئەمەس دېگەن پەند-نەسىھەت كىشىلەر قەلبىگە چوڭقۇر سىڭدى.","seong atini yoqitip at saqlighan bolsa bextsizlik emes dégen pend-nesihet kishiler qelbige chongqur singdi."]],"塞翁失马焉知非福":[["塞翁失马焉知非福，坏事也可能带来好运。","سەئوڭ ئاتىنى يوقىتىپ ئات ساقلىغان بولسا بەختسىزلىك ئەمەس، يامان ئىش ياخشى تەلەي ئېلىپ كېلىشىمۇ مۇمكىن.","seong atini yoqitip at saqlighan bolsa bextsizlik emes, yaman ish yaxshi teley élip kélishimu mumkin."]],"壁癌":[["壁癌会导致墙面出现裂缝。","تام راكى تام يۈزىدە يېرىق پەيدا قىلىدۇ.","tam raki tam yüzide yériq peyda qilidu."]],"寿阳县":[["寿阳县的旅游景点吸引了众多游客。","مۇبارەك يېڭى ناھىيىسىنىڭ ساياھەت مەنزىرلىرى نۇرغۇن ساياھەتچىلەرنى جەلپ قىلدى.","mubarek yéngi nahiyisining sayahet menzirliri nurghun sayahetchilerni jelp qildi."]],"夏尔巴人":[["夏尔巴人生活在喜马拉雅山区。","شارپا خەلقى ھىمالايا تاغلىق رايونىدا ياشايدۇ.","sharpa xelqi himalaya taghliq rayonida yashaydu."]],"坚毅":[["他坚毅的眼神令人敬佩。","ئۇنىڭ مەردانىە كۆزلىرى كىشىنى ھەيران قالدۇرىدۇ.","uning merdanie közliri kishini heyran qalduridu."]],"多久":[["这件事需要多久才能完成？","بۇ ئىش قانچىلىك ۋاقىتتا تاماملىنىدۇ؟","bu ish qanchilik waqitta tamamlinidu?"]],"多子多福":[["多子多福是传统观念。","كۆپ بالىلىق كۆپ بەخت دېگەن ئەنئەنىۋى چۈشەنچە.","köp baliliq köp bext dégen en'eniwi chüshenche."]],"多工化":[["多工化是未来的趋势。","كۆپ ئىشلىمىلىك كەلگۈسىنىڭ يۈزلىنىشى.","köp ishlimilik kelgüsining yüzlinishi."]],"多情":[["他为人多情，乐于助人。","ئۇ كۆپ ھېسسىياتلىق، باشقىلارغا ياردەم قىلىشنى خۇشال كۆرىدۇ.","u köp héssiyatliq, bashqilargha yardem qilishni xushal köridu."]],"大吉岭":[["大吉岭以红茶闻名。","دارجىلىڭ قىزىل چاي بىلەن داڭلىق.","darjiling qizil chay bilen dangliq."]],"夜行军":[["夜行军在月光下秘密行军。","كېچىلىك يۈرۈش قىسىم ئاي نۇرى ئاستىدا مەخپىي يۈرۈش قىلدى.","kéchilik yürüsh qisim ay nuri astida mexpiy yürüsh qildi."]],"大便干燥":[["大便干燥可能是缺水或膳食纤维不足。","چوڭ تەرەتنىڭ قۇرغاقلىقى سۇ ياكى يېمەكلىك تالاسىنىڭ يېتىشمەسلىكىدىن بولۇشى مۇمكىن.","chong teretning qurghaqliqi su yaki yémeklik talasining yétishmeslikidin bolushi mumkin."]],"大客车":[["我们乘坐大客车去郊游。","بىز چوڭ ئاپتوبۇس بىلەن سەيلەنگە چىقتۇق.","biz chong aptobus bilen seylenge chiqtuq."]],"大洲":[["七大洲各有独特的自然风貌。","يەتتە چوڭ قۇرۇقلۇقنىڭ ھەر بىرىنىڭ ئۆزگىچە تەبىئىي مەنزىرىسى بار.","yette chong quruqluqning her birining özgiche tebiiy menzirisi bar."]],"大清早":[["大清早他就出门锻炼了。","ئۇ سەھەر بىلەنلا چىقىپ تەنتەربىيە قىلدى.","u seher bilenla chiqip tenterbiye qildi."]],"大滨鹬":[["大滨鹬是一种栖息于沿海地区的候鸟。","چوڭ قىرغاق چىلى قىرغاق رايونلىرىدا ياشايدىغان كۆچمەن قۇش.","chong qirghaq chili qirghaq rayonlirida yashaydighan köchmen qush."]],"大甲":[["大甲是当地著名的旅游景点。","داجيا يەرلىكنىڭ مەشھۇر ساياھەت نۇقتىسى.","dajya yerlikning meshhur sayahet nuqtisi."]],"大总统":[["大总统是国家最高的行政领袖。","چوڭ پرېزىدېنت دۆلەتنىڭ ئەڭ يۇقىرى مەمۇرىي رەھبىرىدۇر.","chong prézidént döletning eng yuqiri memuriy rehbiridur."]],"大卫·尼尔":[["大卫·尼尔是一位知名作家。","داۋىد نىل داڭلىق يازغۇچىدۇر.","dawid nil dangliq yazghuchidur."]],"大道具":[["舞台上的大道具需要专业人员操作。","سەھنىدىكى چوڭ رېكۋىزىتلارنى كەسپىي خادىملار باشقۇرۇشى كېرەك.","sehnidiki chong rékwizitlarni kespiy xadimlar bashqurushi kérek."]],"多早晚":[["多早晚都会过去的，别太担心。","قانداقلا بولمىسۇن ئۆتۈپ كېتىدۇ، بەك ئەنسىرىمەڭ.","qandaqla bolmisun ötüp kétidu, bek ensirimeng."]],"大马士革李":[["这种水果叫大马士革李。","بۇ مېۋە داماسقۇ ئۆرۈكى دەپ ئاتىلىدۇ.","bu méwe damasqu örüki dep atilidu."]],"天年":[["天年指人的自然寿命。","تەبىئىي ياش ئادەمنىڭ تەبىئىي ئۆمرىنى كۆرسىتىدۇ.","tebiiy yash ademning tebiiy ömrini körsitidu."]],"天水":[["天水是甘肃省的一座城市。","تيەنشۈي گەنسۇ ئۆلكىسىدىكى بىر شەھەردۇر.","tyenshüy gensu ölkisidiki bir sheherdur."]],"天鹅座":[["天鹅座是北天的著名星座。","ئاق قۇ يۇلتۇز تۈركۈمى شىمالىي ئاسماندىكى مەشھۇر يۇلتۇز تۈركۈمىدۇر.","aq qu yultuz türkümi shimaliy asmandiki meshhur yultuz türkümidur."]],"天要落雨，娘要嫁人":[["天要落雨，娘要嫁人，谁也拦不住。","ئاسمان يامغۇر ياغدۇرماقچى، ئانا ياتلىق بولماقچى، ھېچكىم توسالمايدۇ.","asman yamghur yaghdurmaqchi, ana yatliq bolmaqchi, héchkim tosalmaydu."]],"天头":[["天头部分需要仔细处理。","ئاسمان بېشى قىسمىنى ئەستايىدىل بىر تەرەپ قىلىش كېرەك.","asman béshi qismini estayidil bir terep qilish kérek."]],"天祝县":[["天祝县位于甘肃省。","تيەنجۇ ناھىيىسى گەنسۇ ئۆلكىسىدە جايلاشقاندۇر.","tyenju nahiyisi gensu ölkiside jaylashqandur."]],"失之毫厘，差之千里":[["失之毫厘，差之千里，不可掉以轻心。","كىچىك خاتالىق چوڭ پەرقنى كەلتۈرۈپ چىقىرىدۇ، بىپەرۋالىق قىلىشقا بولمايدۇ.","kichik xataliq chong perqni keltürüp chiqiridu, biperwaliq qilishqa bolmaydu."]],"失语症":[["失语症会影响语言能力。","ئېغىز ئېچىلماسلىق كېسىلى تىل ئىقتىدارىغا تەسىر كۆرسىتىدۇ.","éghiz échilmasliq késili til iqtidarigha tesir körsitidu."]],"奈米":[["奈米是一种长度单位。","نانومېتىر بىر ئۇزۇنلۇق بىرلىكىدۇر.","nanométir bir uzunluq birlikidur."]],"奉承讨好":[["他靠奉承讨好上司升迁。","ئۇ خۇشامەت بىلەن ئۈستىدارىنى خۇشال قىلىپ ئەمەل ئاشۇردى.","u xushamet bilen üstidarini xushal qilip emel ashurdi."]],"天路历程":[["他的天路历程充满挑战。","ئۇنىڭ سەمادىي يول سەپىرى خىرىسلارغا تولغان.","uning semadiy yol sepiri xirislargha tolghan."]],"奠基者":[["奠基者功不可没。","يەكتەك سالغۇچىلارنىڭ تۆھپىسى ئۇنتۇلغۇسىز.","yektek salghuchilarning töhpisi untulghusiz."]],"套换":[["他决定把旧手机套换新的。","ئۇ كونا تېلېفون يۈرۈمىنى يېڭىسىغا ئالماشتۇرۇشنى قارار قىلدى.","u kona téléfon yürümini yéngisigha almashturushni qarar qildi."]],"套牢":[["他的资金被套牢在股市中。","ئۇنىڭ مەبلىغى پاي بازىرىدا يۈرۈمگە چۆكۈپ قالدى.","uning meblighi pay bazirida yürümge chöküp qaldi."]],"套红":[["报纸套红部分格外醒目。","گېزىتنىڭ يۈرۈم قىزىل بۆلىكى ئالاھىدە كۆزگە چېلىقىدۇ.","gézitning yürüm qizil böliki alahide közge chéliqidu."]],"套索":[["牛仔用套索套住野马。","كابوي يۈرۈم ئارقان بىلەن ياۋا ئاتنى يۈرۈملىدى.","kaboy yürüm arqan bilen yawa atni yürümlidi."]],"奥数":[["奥数竞赛吸引了众多学生。","ئولىمپىيادا ماتېماتىكا مۇسابىقىسى نۇرغۇن ئوقۇغۇچىلارنى جەلپ قىلدى.","olimpiyada matématika musabiqisi nurghun oqughuchilarni jelp qildi."]],"奸臣":[["奸臣误国害民。","خائىن ۋەزىرلەر دۆلەتكە زىيان يەتكۈزۈپ خەلقنى زىيانغا ئۇچرىتىدۇ.","xain wezirler döletke ziyan yetküzüp xelqni ziyangha uchritidu."]],"奶蛋素":[["奶蛋素饮食包含牛奶和鸡蛋。","سۈت ۋە تۇخۇم يېمەكلىكى سۈت بىلەن تۇخۇمنى ئۆز ئىچىگە ئالىدۇ.","süt we tuxum yémekliki süt bilen tuxumni öz ichige alidu."]],"奥委会":[["国际奥委会负责奥运会的组织工作。","خەلقئارا ئولىمپىك كومىتېتى ئولىمپىك ئويۇنلىرىنى تەشكىللەش خىزمىتىگە مەسئۇل.","xelq'ara olimpik komitéti olimpik oyunlirini teshkillesh xizmitige mes'ul."]],"好好学习，天天向上":[["我们要好好学习，天天向上，努力进步。","بىز ياخشى ئۆگىنىپ، كۈندىن-كۈنگە ئىلگىرىلەپ، تىرىشىپ تەرەققىي قىلىشىمىز كېرەك.","biz yaxshi öginip, kündin-künge ilgirilep, tiriship tereqqiy qilishimiz kérek."]],"好意思":[["你还好意思说这种话？","سەن يەنە بۇنداق گەپ قىلىشقا ئۇيالمايۋاتامسەن؟","sen yene bundaq gep qilishqa uyalmaywatamsen?"]],"好为人师":[["他总是好为人师，爱管闲事。","ئۇ ھەمىشە باشقىلارغا ئۇستازلىق قىلىشنى ياخشى كۆرىدۇ، بىكار ئىشلارغا ئارىلىشىشنى ياخشى كۆرىدۇ.","u hemishe bashqilargha ustazliq qilishni yaxshi köridu, bikar ishlargha arilishishni yaxshi köridu."]],"威灵顿":[["威灵顿战役改变了历史。","ۋېيللىڭتون جېڭى تارىخنى ئۆزگەرتتى.","wéyllington jéngi tarixni özgertti."]],"威化饼干":[["孩子们爱吃威化饼干。","بالىلار ۋافېل پىشۇرۇقىنى يېيىشنى ياخشى كۆرىدۇ.","balilar wafél pishuruqini yéyishni yaxshi köridu."]],"姬路城":[["姬路城是日本著名的古城。","خىمېجى قەلئەسى ياپونىيەنىڭ مەشھۇر قەدىمكى شەھىرى.","ximéji qel'esi yaponiyening meshhur qedimki shehiri."]],"姜文":[["姜文是中国知名导演和演员。","جياڭۋېن جۇڭگونىڭ تونۇلغان رېژىسسورى ۋە ئارتىسى.","jyangwén junggoning tonulghan rézhissori we artisi."]],"始祖":[["人类最早的始祖生活在树上。","ئىنسانىيەتنىڭ ئەڭ قەدىمكى ئەجدادلىرى دەرەخلەردە ياشىغان.","insaniyetning eng qedimki ejdadliri derexlerde yashighan."]],"妈卖批":[["他气得大喊“妈卖批”。","ئۇ ئاچچىقىدا «ئاپام ساتسۇن» دەپ قىچقىردى.","u achchiqida «apam satsun» dep qichqirdi."]],"字面":[["字面指的是字的外观形式。","خەت يۈزى خەتنىڭ تاشقى كۆرۈنۈش شەكلىنى كۆرسىتىدۇ.","xet yüzi xetning tashqi körünüsh sheklini körsitidu."]],"孟浪":[["孟浪的行为常常让人感到意外。","مېڭلاڭ قىلمىشلىرى كۆپىنچە كىشىلەرنى ھەيران قالدۇرىدۇ.","ménglang qilmishliri köpinche kishilerni heyran qalduridu."]],"安于现状":[["她安于现状，不愿改变。","ئۇ ھازىرقى ئەھۋالغا كۆنۈپ، ئۆزگەرتىشنى خالىمايدۇ.","u hazirqi ehwalgha könüp, özgertishni xalimaydu."]],"安泽县":[["安泽县拥有丰富的煤炭资源。","ئەنزې ناھىيىسى مول كۆمۈر بايلىقىغا ئىگە.","enzé nahiyisi mol kömür bayliqigha ige."]],"孩奴":[["他成了孩子的孩奴，毫无自由。","ئۇ بالىلىرىنىڭ قۇلىغا ئايلانىپ، ھېچقانداق ئەركىنلىكى يوق.","u balilirining quligha aylanip, héchqandaq erkinliki yoq."]],"安得拉邦":[["安得拉邦是印度的一个邦。","ئەندىرا پرادېش ھىندىستاننىڭ بىر شتاتىدۇر.","endira pradésh hindistanning bir shtatidur."]],"客服":[["客服团队会尽快回复您的咨询。","ئابونتلار مۇلازىمەت گۇرۇپپىسى سىزنىڭ سورىغىنىڭىزغا تېزدىن جاۋاب قايتۇرىدۇ.","abontlar mulazimet guruppisi sizning sorighiningizgha tézdin jawab qayturidu."]],"客气话":[["这些客气话只是礼貌的客套而已。","بۇ ئەدەپلىك سۆزلەر پەقەت ئەدەپ-تەكەللۇپ سۆزلىرىدىن ئىبارەت.","bu edeplik sözler peqet edep-tekellup sözliridin ibaret."]],"宣传部":[["宣传部负责策划各类宣传活动。","تەشۋىقات بۆلۈمى ھەر خىل تەشۋىقات پائالىيەتلىرىنى پىلانلاشقا مەسئۇل.","teshwiqat bölümi her xil teshwiqat paaliyetlirini pilanlashqa mes'ul."]],"定情":[["他们通过音乐定情。","ئۇلار مۇزىكا ئارقىلىق مۇھەببەت باغلىدى.","ular muzika arqiliq muhebbet baghlidi."]],"定期存款":[["定期存款利率较高。","مۇددەتلىك ئامانەت قويۇشنىڭ ئۆسۈم نىسبىتى بىر قەدەر يۇقىرى.","muddetlik amanet qoyushning ösüm nisbiti bir qeder yuqiri."]],"宜兰县":[["宜兰县的农产品质量上乘。","يىلان ناھىيىسىنىڭ يېزا ئىگىلىك مەھسۇلاتلىرىنىڭ سۈپىتى ئالاھىدە يۇقىرى.","yilan nahiyisining yéza igilik mehsulatlirining süpiti alahide yuqiri."]],"宿务语":[["宿务语是当地语言。","سېبۇ تىلى يەرلىك تىل.","sébu tili yerlik til."]],"宿城区":[["宿城区是当地的政治中心。","سۇچېڭ رايونى يەرلىك سىياسىي مەركەز.","suchéng rayoni yerlik siyasiy merkez."]],"宿弊":[["改革旨在消除长期存在的宿弊。","ئىسلاھات ئۇزۇندىن بۇيان مەۋجۇت بولغان كونا ئەيىبلەرنى يوقىتىشنى مەقسەت قىلىدۇ.","islahat uzundin buyan mewjut bolghan kona eyiblerni yoqitishni meqset qilidu."]],"家计":[["家计需要精打细算才能维持。","ئائىلە چىقىمىنى ئېھتىياتچانلىق بىلەن ھېسابلاپ تۇتۇش كېرەك.","aile chiqimini éhtiyatchanliq bilen hésablap tutush kérek."]],"宜丰县":[["宜丰县位于江西省北部。","يىفېڭ ناھىيىسى جياڭشى ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","yiféng nahiyisi jyangshi ölkisining shimalida jaylashqan."]],"实力主义":[["实力主义盛行一时。","كۈچ-قۇدرەتچىلىك بىر مەزگىل ئومۇملاشتى.","küch-qudretchilik bir mezgil omumlashti."]],"密山":[["密山是黑龙江省的一个著名景点。","مىشەن خېيلۇڭجياڭ ئۆلكىسىدىكى مەشھۇر مەنزىرە نۇقتىسى.","mishen xéylungjyang ölkisidiki meshhur menzire nuqtisi."]],"宁陵县":[["宁陵县以梨树闻名。","نىڭلىڭ ناھىيىسى ئامۇت بىلەن داڭلىق.","ningling nahiyisi amut bilen dangliq."]],"富纳富提":[["富纳富提是太平洋上的岛屿。","فۇنافۇتى تىنچ ئوكياندىكى ئارال.","funafuti tinch okyandiki aral."]],"富户":[["古代富户常常捐钱修路。","قەدىمكى باي ئائىلىلەر دائىم پۇل ئىئانە قىلىپ يول سالدۇراتتى.","qedimki bay aililer daim pul iane qilip yol salduratti."]],"察哈尔":[["察哈尔族是中国的一个少数民族。","چاخار مىللىتى جۇڭگونىڭ بىر ئاز سانلىق مىللىتى.","chaxar milliti junggoning bir az sanliq milliti."]],"寸口":[["医生通过寸口把脉诊断病情。","دوختۇر بىلەك تومۇرى ئارقىلىق تومۇر تۇتۇپ كېسەللىكنى دىئاگنوز قىلىدۇ.","doxtur bilek tomuri arqiliq tomur tutup késellikni diagnoz qilidu."]],"封二":[["封二位置常用于展示产品特写。","ئىككىنچى مۇقاۋا ئورنى ئادەتتە مەھسۇلاتنىڭ يېقىن كۆرۈنۈشىنى كۆرسىتىشكە ئىشلىتىلىدۇ.","ikkinchi muqawa orni adette mehsulatning yéqin körünüshini körsitishke ishlitilidu."]],"射灯":[["舞台上的射灯营造出强烈的光影效果。","سەھنىدىكى نۇر چىرىغى كۈچلۈك نۇر-سايە تەسىرى يارىتىدۇ.","sehnidiki nur chirighi küchlük nur-saye tesiri yaritidu."]],"封里":[["包裹被仔细封里。","بوغچا ئېھتىيات بىلەن ئورالغان.","boghcha éhtiyat bilen oralghan."]],"小不忍则乱大谋":[["小不忍则乱大谋。","كىچىك ئىشقا چىدىمىسەڭ چوڭ ئىشنى بۇزىسەن.","kichik ishqa chidimiseng chong ishni buzisen."]],"小人得志":[["小人得志后嚣张。","كىچىك ئادەم مەقسىتىگە يەتكەندىن كېيىن تەكەببۇرلىنىدۇ.","kichik adem meqsitige yetkendin kéyin tekebburlinidu."]],"专属":[["这家银行提供专属的财富管理咨询服务。","بۇ بانكا مەخسۇس بايلىق باشقۇرۇش مەسلىھەت مۇلازىمىتى تەمىنلەيدۇ.","bu banka mexsus bayliq bashqurush meslihet mulazimiti teminleydu."]],"对着干":[["他偏要对着干，不肯妥协。","ئۇ قەستەن قارشى تۇرۇشنى تاللاپ، مۇرەسسە قىلىشنى رەت قىلدى.","u qesten qarshi turushni tallap, muresse qilishni ret qildi."]],"将计就计":[["他决定将计就计。","ئۇ پىلاننى پىلانغا قارشى قوللىنىشنى قارار قىلدى.","u pilanni pilangha qarshi qollinishni qarar qildi."]],"小集团":[["这个小集团经常组织户外活动。","بۇ كىچىك گۇرۇھ كۆپىنچە سىرتقى پائالىيەتلەرنى تەشكىللەيدۇ.","bu kichik guruh köpinche sirtqi paaliyetlerni teshkilleydu."]],"小试牛刀":[["他小试牛刀，表现不错。","ئۇ ئۆزىنى سىناپ باقتى، ئىپادىسى يامان ئەمەس.","u özini sinap baqti, ipadisi yaman emes."]],"小颚":[["小颚的构造十分独特。","كىچىك ئېڭەكنىڭ قۇرۇلمىسى ئىنتايىن ئۆزگىچە.","kichik éngekning qurulmisi intayin özgiche."]],"尼安德特人":[["尼安德特人生活在旧石器时代。","نىئاندرتال ئادەم كونا تاش قورال دەۋرىدە ياشىغان.","niandrtal adem kona tash qoral dewride yashighan."]],"少府":[["少府是古代掌管宫廷事务的机构。","شاۋفۇ قەدىمدە ساراي ئىشلىرىنى باشقۇرىدىغان ئورگان ئىدى.","shawfu qedimde saray ishlirini bashquridighan organ idi."]],"少东家":[["少东家接手了家族企业。","ياش خوجايىن ئائىلە كارخانىسىنى ئۆتكۈزۈۋالدى.","yash xojayin aile karxanisini ötküzüwaldi."]],"尿床":[["他小时候经常尿床。","ئۇ كىچىك ۋاقتىدا دائىم كارىۋاتقا سۈيدۈك قىلاتتى.","u kichik waqtida daim kariwatqa süydük qilatti."]],"山贼":[["山贼常常在偏僻的山路上抢劫。","تاغ قاراقچىلىرى كۆپىنچە چەت-ياقا تاغ يوللىرىدا بۇلاڭ-تالاڭ قىلىدۇ.","tagh qaraqchiliri köpinche chet-yaqa tagh yollirida bulang-talang qilidu."]],"屯区":[["这个屯区是当地重要的农业生产基地。","بۇ تۇن رايونى يەرلىكنىڭ مۇھىم يېزا ئىگىلىك ئىشلەپچىقىرىش بازىسىدۇر.","bu tun rayoni yerlikning muhim yéza igilik ishlepchiqirish bazisidur."]],"局部作用域":[["局部作用域限制变量范围。","لوكال ئىشلەتكۈچى دائىرىسى ئۆزگەرگۈچىلەرنىڭ دائىرىسىنى چەكلەيدۇ.","lokal ishletküchi dairisi özgergüchilerning dairisini chekleydu."]],"崇州市":[["崇州市经济繁荣。","چوڭجو شەھىرىنىڭ ئىقتىسادى گۈللەنمەكتە.","chongjo shehirining iqtisadi güllenmekte."]],"昆士兰":[["昆士兰是澳大利亚的州。","كۇينسلاند ئاۋسترالىيەنىڭ بىر شىتاتى.","kuynsland awstraliyening bir shitati."]],"昆山":[["昆山是江苏省的一座城市。","كۇنشەن جياڭسۇ ئۆلكىسىدىكى بىر شەھەر.","kunshen jyangsu ölkisidiki bir sheher."]],"崔鸿":[["崔鸿是古代的一位官员。","چۇي خۇڭ قەدىمكى زاماندىكى بىر ئەمەلدار.","chuy xung qedimki zamandiki bir emeldar."]],"崖壁":[["崖壁陡峭险峻。","يار ئېتىكى تىك ۋە خەتەرلىك.","yar étiki tik we xeterlik."]],"川端康成":[["川端康成是日本著名的作家。","چۈەندۈەن ياسۇنارى ياپونىيەنىڭ مەشھۇر يازغۇچىسى.","chüendüen yasunari yaponiyening meshhur yazghuchisi."]],"巡捕房":[["巡捕房负责管理辖区治安。","شۈنبوخاڭ باشقۇرۇش رايونىنىڭ جەمئىيەت تەرتىپىنى باشقۇرۇشقا مەسئۇل.","shünboxang bashqurush rayonining jem'iyet tertipini bashqurushqa mes'ul."]],"崂山区":[["崂山区以海滨风光闻名。","لاۋشەن رايونى دېڭىز بويى مەنزىرىسى بىلەن داڭلىق.","lawshen rayoni déngiz boyi menzirisi bilen dangliq."]],"工作面":[["这个工程的工作面非常复杂。","بۇ قۇرۇلۇشنىڭ خىزمەت يۈزى ئىنتايىن مۇرەككەپ.","bu qurulushning xizmet yüzi intayin murekkep."]],"岩穴":[["岩穴是岩石中自然形成的洞穴。","تاش ئۆڭكۈر تاش ئىچىدە تەبىئىي شەكىللەنگەن غار.","tash öngkür tash ichide tebiiy shekillengen ghar."]],"工商界":[["工商界代表参加了会议。","سودا-سانائەت ساھەسىنىڭ ۋەكىللىرى يىغىنغا قاتناشتى.","soda-sanaet sahesining wekilliri yighingha qatnashti."]],"左云":[["左云是个历史悠久的小城。","سول بۇلۇت ئۇزۇن تارىخقا ئىگە كىچىك شەھەردۇر.","sol bulut uzun tarixqa ige kichik sheherdur."]],"巧干":[["巧干比蛮干更有效率。","ماھىرانە ئىشلەش كۈچ سېلىپ ئىشلەشتىن تېخىمۇ ئۈنۈملۈكتۇر.","mahirane ishlesh küch sélip ishleshtin téximu ünümlüktur."]],"市场定位":[["品牌的市场定位直接影响其消费者群体。","ماركىنىڭ بازار ئورنى ئۇنىڭ ئىستېمالچىلار گۇرۇپپىسىغا بىۋاسىتە تەسىر كۆرسىتىدۇ.","markining bazar orni uning istémalchilar guruppisigha biwasite tesir körsitidu."]],"布城":[["布城是马来西亚的行政中心。","بۇتراجاي مالايسىيەنىڭ مەمۇرىي مەركىزىدۇر.","butrajay malaysiyening memuriy merkizidur."]],"市民社会":[["市民社会是民主制度的重要基础。","شەھەرلىك جەمئىيەت دېموكراتىك تۈزۈمنىڭ مۇھىم ئاساسىدۇر.","sheherlik jem'iyet démokratik tüzümning muhim asasidur."]],"布尔津县":[["布尔津县位于新疆北部。","بۇرچىن ناھىيىسى شىنجاڭنىڭ شىمالىدا جايلاشقان.","burchin nahiyisi shinjangning shimalida jaylashqan."]],"巴戟":[["巴戟是一种常用的中药材。","باجى دورا ماتېرىيالىنىڭ بىر خىلى.","baji dora matériyalining bir xili."]],"希拉里·克林顿":[["希拉里·克林顿是美国前第一夫人。","ھىلارى كلىنتون ئامېرىكىنىڭ سابىق بىرىنچى خانىمىدۇر.","hilari klinton amérikining sabiq birinchi xanimidur."]],"庖牺氏":[["庖牺氏是中国古代的重要人物。","پاۋشى ئەپەندى جۇڭگونىڭ قەدىمكى زامانىدىكى مۇھىم شەخس.","pawshi ependi junggoning qedimki zamanidiki muhim shexs."]],"平型关大捷":[["平型关大捷鼓舞了全国军民。","پىڭشىڭگۇان غەلىبىسى پۈتۈن مەملىكەتتىكى ئارمىيە ۋە خەلقنى روھلاندۇردى.","pingshingguan ghelibisi pütün memlikettiki armiye we xelqni rohlandurdi."]],"干话":[["别再说那些干话了，直接行动吧！","ئەمدى قۇرۇق گەپلەرنى قىلما، بىۋاسىتە ھەرىكەتكە ئۆت.","emdi quruq geplerni qilma, biwasite heriketke öt."]],"店面":[["店面装修得简洁而大方。","دۇكان يۈزى ئاددىي ۋە كەڭ كۆڭۈللۈك بېزەلگەن.","dukan yüzi addiy we keng köngüllük bézelgen."]],"庚寅":[["庚寅年对应着特定的历史时期。","گېڭيىن يىلى مەلۇم بىر تارىخىي دەۋرگە ماس كېلىدۇ.","géngyin yili melum bir tarixiy dewrge mas kélidu."]],"广平县":[["广平县拥有丰富的煤炭资源。","گۇاڭپىڭ ناھىيىسى مول كۆمۈر بايلىقىغا ئىگە.","guangping nahiyisi mol kömür bayliqigha ige."]],"弓箭步":[["他练习弓箭步时动作标准。","ئۇ يايلا-ئوق پۇت ئۇسۇلىنى مەشىق قىلغاندا ھەرىكىتى ئۆلچەملىك.","u yayla-oq put usulini meshiq qilghanda herikiti ölchemlik."]],"张秋":[["张秋是一位著名的文学评论家。","جاڭ چيۇ مەشھۇر بىر ئەدەبىي تەنقىدچى.","jang chyu meshhur bir edebiy tenqidchi."]],"彭丽媛":[["彭丽媛是中国著名的歌唱家。","پېڭ لىيۈەن جۇڭگونىڭ داڭلىق ناخشىچىسى.","péng liyüen junggoning dangliq naxshichisi."]],"役龄":[["役龄通常从成年开始计算。","ئىش يېشى ئادەتتە چوڭ بولغاندىن باشلاپ ھېسابلىنىدۇ.","ish yéshi adette chong bolghandin bashlap hésablinidu."]],"后信号灯":[["后信号灯坏了，导致交通拥堵。","كېيىنكى سىگنال چىرىغى بۇزۇلۇپ، قاتناش توسۇلۇشقا سەۋەب بولدى.","kéyinki signal chirighi buzulup, qatnash tosulushqa seweb boldi."]],"弹射":[["火箭弹被弹射了出去。","راكېتا ئوقى ئېتىلىپ چىقتى.","rakéta oqi étilip chiqti."]],"径路":[["这条径路通往山顶。","بۇ يول تاغ چوققىسىغا ئېلىپ بارىدۇ.","bu yol tagh choqqisigha élip baridu."]],"得道多助":[["得道多助，这是自古以来的真理。","ئەخلاق يولىدا ماڭغان كىشىگە كۆپ ياردەم قىلىنىدۇ، بۇ قەدىمدىن تارتىپ كەلگەن ھەقىقەت.","exlaq yolida mangghan kishige köp yardem qilinidu, bu qedimdin tartip kelgen heqiqet."]],"徐闻":[["徐闻是广东省的一个沿海城市。","شۈۋېن گۇاڭدۇڭ ئۆلكىسىنىڭ دېڭىز بويى شەھىرى.","shüwén guangdung ölkisining déngiz boyi shehiri."]],"复盘":[["团队对项目进行了复盘分析。","گۇرۇپپا تۈر ئۈستىدە قايتا تەھلىل ئېلىپ باردى.","guruppa tür üstide qayta tehlil élip bardi."]],"心血管疾病":[["高血压属于心血管疾病的一种。","يۇقىرى قان بېسىمى يۈرەك-قان تومۇر كېسەللىكلىرىنىڭ بىر تۈرىگە كىرىدۇ.","yuqiri qan bésimi yürek-qan tomur késelliklirining bir türige kiridu."]],"心慌意乱":[["她吓得心慌意乱。","ئۇ قورقۇنچتىن كۆڭلى بۇزۇلۇپ قالدى.","u qorqunchtin köngli buzulup qaldi."]],"急驰":[["赛车在赛道上急驰，速度极快。","مۇسابىقە ماشىنىسى ترېك ئۈستىدە ئىنتايىن تېز سۈرئەتتە چاپماقتا.","musabiqe mashinisi trék üstide intayin téz sür'ette chapmaqta."]],"怫然":[["他怫然变色，十分不高兴。","ئۇنىڭ رەڭگى ئۆزگىرىپ، ئىنتايىن خۇشال ئەمەس ھالەتكە كەلدى.","uning renggi özgirip, intayin xushal emes haletke keldi."]],"怯场":[["他第一次上台表演时非常怯场。","ئۇ تۇنجى قېتىم سەھنىگە چىققاندا ئىنتايىن تارتىنچاقلىق كۆرسەتتى.","u tunji qétim sehnige chiqqanda intayin tartinchaqliq körsetti."]],"心碎":[["他的心碎成千万片，再也无法拼合。","ئۇنىڭ يۈرىكى مىڭ پارچە بولۇپ چېقىلىپ، ئەمدى ھەرگىز بىرلەشتۈرگىلى بولمايدۇ.","uning yüriki ming parche bolup chéqilip, emdi hergiz birleshtürgili bolmaydu."]],"惆怅若失":[["她显得惆怅若失，心事重重。","ئۇ ئۆزىنى يوقىتىپ قويغاندەك ھېس قىلىپ، كۆڭلى ئېغىر ئىدى.","u özini yoqitip qoyghandek hés qilip, köngli éghir idi."]],"意会":[["我们无需言语便意会彼此。","بىز سۆزسىزلا بىر-بىرىمىزنى چۈشىنىمىز.","biz sözsizla bir-birimizni chüshinimiz."]],"惨绝人寰":[["这种罪行惨绝人寰。","بۇنداق جىنايەت دۇنيادا كۆرۈلۈپ باقمىغان ئېچىنىشلىقتۇر.","bundaq jinayet dunyada körülüp baqmighan échinishliqtur."]],"爱才若渴":[["公司老板对人才爱才若渴。","شىركەت رەئىسى ئىقتىدارلىق كىشىلەرگە ئىنتايىن تەلۋە.","shirket reisi iqtidarliq kishilerge intayin telwe."]],"想想看":[["想想看，这样做真的对吗？","ئويلىنىپ باقايلى، بۇنداق قىلىش ھەقىقەتەن توغرامۇ؟","oylinip baqayli, bundaq qilish heqiqeten toghramu?"]],"感化院":[["感化院致力于帮助迷途者回归正途。","تەربىيە ئورنى ئازغانلارنى توغرا يولغا قايتۇرۇشقا تىرىشىدۇ.","terbiye orni azghanlarni toghra yolgha qayturushqa tirishidu."]],"怀柔县":[["怀柔县曾是历史上的重要地区。","خۇەيروۋ ناھىيىسى تارىختا مۇھىم بىر رايون ئىدى.","xueyrow nahiyisi tarixta muhim bir rayon idi."]],"戒命":[["皇帝颁布戒命，禁止民众外出。","ئىمپېراتور چەكلەش پەرمانى چىقىرىپ، خەلقنىڭ سىرتقا چىقىشىنى چەكلىدى.","impérator cheklesh permani chiqirip, xelqning sirtqa chiqishini cheklidi."]],"应县":[["应县历史悠久，文化底蕴深厚。","يىڭشيەن ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيەت ئاساسى چوڭقۇر.","yingshyen nahiyisining tarixi uzun, medeniyet asasi chongqur."]],"打伞":[["下雨时别忘了打伞。","يامغۇر ياغقاندا كۈنلۈك ئېلىشنى ئۇنۇتماڭ.","yamghur yaghqanda künlük élishni unutmang."]],"手杖":[["老人拄着手杖慢慢走在路上。","بوۋاي ھاسىسىغا تايىنىپ ئاستا يولدا ماڭدى.","boway hasisigha tayinip asta yolda mangdi."]],"托卡塔":[["托卡塔是钢琴曲。","توككاتا پىيانىنو مۇزىكىسىدۇر.","tokkata piyanino muzikisidur."]],"扳罾":[["渔民用扳罾捕鱼。","بېلىقچىلار تور بىلەن بېلىق تۇتىدۇ.","béliqchilar tor bilen béliq tutidu."]],"成千累万":[["成千累万的财富难以计数。","مىڭلىغان-تۈمەنلىگەن بايلىقنى ساناپ تۈگەتكىلى بولمايدۇ.","minglighan-tümenligen bayliqni sanap tügetkili bolmaydu."]],"批评家":[["这位批评家对电影提出了尖锐意见。","بۇ تەنقىدچى كىنوغا ئۆتكۈر پىكىر بەردى.","bu tenqidchi kinogha ötkür pikir berdi."]],"承重孙":[["承重孙负责设计承重结构。","يۈك كۆتۈرۈش نەۋرىسى يۈك كۆتۈرۈش قۇرۇلمىسىنى لايىھىلەشكە مەسئۇل.","yük kötürüsh newrisi yük kötürüsh qurulmisini layihileshke mes'ul."]],"把舵":[["船长负责把舵，确保航行安全。","كاپىتان رولنى تۇتۇشقا مەسئۇل بولۇپ، سەپەر بىخەتەرلىكىنى كاپالەتكە ئىگە قىلىدۇ.","kapitan rolni tutushqa mes'ul bolup, seper bixeterlikini kapaletke ige qilidu."]],"抗菌素":[["青霉素是一种常见抗菌素。","پېنىتسىللىن كۆپ ئۇچرايدىغان بىر خىل باكتېرىيەگە قارشى دورا.","pénitsillin köp uchraydighan bir xil baktériyege qarshi dora."]],"拉比":[["拉比是一位著名的音乐家。","رابى مەشھۇر مۇزىكانت.","rabi meshhur muzikant."]],"招牌菜":[["招牌菜是红烧肉配米饭。","ئاتاقلىق تاماق قىزىل پىشۇرۇلغان گۆش بىلەن گۈرۈچ.","ataqliq tamaq qizil pishurulghan gösh bilen gürüch."]],"拱手相让":[["冠军头衔最终拱手相让给了对手。","چېمپىيونلۇق نامى ئاخىرىدا رەقىبىگە بېرىۋېتىلدى.","chémpiyonluq nami axirida reqibige bériwétildi."]],"拾物":[["保安拾物后及时归还了失主的物品。","قوغدىغۇچى تېپىۋالغان نەرسىنى ۋاقتىدا ئىگىسىگە قايتۇردى.","qoghdighuchi tépiwalghan nersini waqtida igisige qayturdi."]],"指甲盖":[["指甲盖上有明显的月牙形。","تىرناق قاپقىقىدا ئېنىق ئاي شەكلى بار.","tirnaq qapqiqida éniq ay shekli bar."]],"授乳":[["母亲正在给宝宝授乳。","ئانا بوۋاققا سۈت بېرىۋاتىدۇ.","ana bowaqqa süt bériwatidu."]],"提任":[["他被提任为部门主管。","ئۇ بۆلۈم باشلىقى بولۇپ تەيىنلەندى.","u bölüm bashliqi bolup teyinlendi."]],"换位":[["他主动和队友换位。","ئۇ تەشەببۇسكارلىق بىلەن يولداشلىرى بىلەن ئورۇن ئالماشتۇردى.","u teshebbuskarliq bilen yoldashliri bilen orun almashturdi."]],"挥翰":[["他挥翰写下一首诗。","ئۇ قەلەم تەۋرىتىپ بىر شېئىر يازدى.","u qelem tewritip bir shéir yazdi."]],"挚情":[["她的挚情深深打动了我。","ئۇنىڭ سەمىمىي مۇھەببىتى مېنى چوڭقۇر تەسىرلەندۈردى.","uning semimiy muhebbiti méni chongqur tesirlendürdi."]],"撒马利亚":[["撒马利亚是古代的一个地区。","سامارىيە قەدىمكى زاماندىكى بىر رايون.","samariye qedimki zamandiki bir rayon."]],"摩梭族":[["摩梭族以母系社会闻名于世。","موسو مىللىتى ئانا تەرەپلىك جەمئىيەت بىلەن دۇنياغا تونۇلغان.","moso milliti ana tereplik jem'iyet bilen dunyagha tonulghan."]],"据料":[["据料，明天天气会转晴。","تەخمىن قىلىنىشىچە، ئەتە ھاۋا ئېچىلىدۇ.","texmin qilinishiche, ete hawa échilidu."]],"收报人":[["收报人负责接收信息。","تېلېگرامما ئالغۇچى ئۇچۇرنى قوبۇل قىلىشقا مەسئۇل.","télégramma alghuchi uchurni qobul qilishqa mes'ul."]],"收报机":[["收报机发出“嘀嘀”的声响。","تېلېگرامما ئالغۇچى ماشىنا «دىڭ-دىڭ» ئاۋاز چىقاردى.","télégramma alghuchi mashina «ding-ding» awaz chiqardi."]],"收尾音":[["这首曲子的收尾音特别动人。","بۇ كۈينىڭ ئاخىرقى ئاۋازى ئالاھىدە تەسىرلىك.","bu küyning axirqi awazi alahide tesirlik."]],"拦网":[["拦网阻止了球进入。","تور توپنىڭ كىرىشىنى توسۇپ قالدى.","tor topning kirishini tosup qaldi."]],"攘窃":[["防止物品被攘窃。","بۇيۇملارنىڭ ئوغرىلىنىشىنىڭ ئالدىنى ئېلىش.","buyumlarning oghrilinishining aldini élish."]],"文牒":[["文牒是古代通行的官方文书。","ۋېنديې قەدىمكى زاماندا يول يۈرۈشتە ئىشلىتىلگەن رەسمىي ھۆججەتتۇر.","wéndyé qedimki zamanda yol yürüshte ishlitilgen resmiy höjjettur."]],"整队":[["同学们迅速整队集合。","ئوقۇغۇچىلار تېز پۈتۈنلەي سەپكە تىزىلدى.","oqughuchilar téz pütünley sepke tizildi."]],"斜率":[["直线的斜率可以表示倾斜程度。","توغرا سىزىقنىڭ يانتايلىق دەرىجىسى مايىللىق دەرىجىسىنى ئىپادىلىيەلەيدۇ.","toghra siziqning yantayliq derijisi mayilliq derijisini ipadiliyeleydu."]],"斜眼看":[["她斜眼看着桌上的文件。","ئۇ ئۈستەلدىكى ھۆججەتلەرگە يانتايىپ قارىدى.","u üsteldiki höjjetlerge yantayip qaridi."]],"数黑论黄":[["这种说法数黑论黄，毫无根据。","بۇنداق قارىنى ئاق دەپ قاراشنىڭ ھېچقانداق ئاساسى يوق.","bundaq qarini aq dep qarashning héchqandaq asasi yoq."]],"新军":[["新军士气高昂。","يېڭى ئارمىيەنىڭ روھى يۇقىرى.","yéngi armiyening rohi yuqiri."]],"新绛":[["新绛的古城墙保存完好。","يېڭجياڭنىڭ قەدىمىي شەھەر تامى ياخشى ساقلىنىپ قالغان.","yéngjyangning qedimiy sheher tami yaxshi saqlinip qalghan."]],"方庄":[["方庄是北京的著名居住区。","فاڭجۇاڭ بېيجىڭنىڭ داڭلىق تۇرالغۇ رايونى.","fangjuang béyjingning dangliq turalghu rayoni."]],"旌德":[["旌德以优美的自然风光闻名。","جىڭدې گۈزەل تەبىئىي مەنزىرىسى بىلەن داڭلىق.","jingdé güzel tebiiy menzirisi bilen dangliq."]],"日光灯":[["办公室的日光灯非常明亮。","ئىشخانىنىڭ كۈندۈزى چىرىغى ئىنتايىن يورۇق.","ishxanining kündüzi chirighi intayin yoruq."]],"日电电子":[["日电电子是知名品牌。","كۈندىلىك ئېلېكترونلۇق ئۈسكۈنە تونۇلغان ماركا.","kündilik éléktronluq üsküne tonulghan marka."]],"春困":[["春天容易感到春困，需要多休息。","باھاردا ئاسانلا باھار ھارغىنلىقى ھېس قىلىنىدۇ، كۆپرەك ئارام ئېلىش كېرەك.","baharda asanla bahar harghinliqi hés qilinidu, köprek aram élish kérek."]],"春黄菊":[["春黄菊是常见的观赏花卉。","باھار خېرىزانتېمى ئادەتتىكى مەنزىرە گۈلى.","bahar xérizantémi adettiki menzire güli."]],"时不我待":[["时不我待，必须努力。","ۋاقىت مېنى ساقلىمايدۇ، چوقۇم تىرىشىش كېرەك.","waqit méni saqlimaydu, choqum tirishish kérek."]],"晚清":[["晚清时期社会动荡不安。","كېيىنكى چىڭ سۇلالىسى دەۋرىدە جەمئىيەت قالايمىقان ئىدى.","kéyinki ching sulalisi dewride jem'iyet qalaymiqan idi."]],"晚礼服":[["她穿上晚礼服显得格外优雅。","ئۇ كەچلىك كۆينەك كىيىپ ئالاھىدە نەپىس كۆرۈندى.","u kechlik köynek kiyip alahide nepis köründi."]],"普通翠鸟":[["普通翠鸟以小鱼为主要食物。","ئادەتتىكى زۇمرەت قۇشى كىچىك بېلىقلارنى ئاساسىي ئوزۇق قىلىدۇ.","adettiki zumret qushi kichik béliqlarni asasiy ozuq qilidu."]],"暖流":[["暖流带来了温暖的气候变化。","ئىللىق ئېقىم ئىللىق ئىقلىم ئۆزگىرىشىنى ئېلىپ كەلدى.","illiq éqim illiq iqlim özgirishini élip keldi."]],"暖阁":[["暖阁是古代建筑中用于取暖的房间。","ئىللىق ئۆي قەدىمكى بىناكارلىقتا ئىسسىنىش ئۈچۈن ئىشلىتىلگەن ئۆي.","illiq öy qedimki binakarliqta issinish üchün ishlitilgen öy."]],"景福宫":[["景福宫是韩国的重要古迹。","جىڭفۇ سارىيى كورېيەنىڭ مۇھىم تارىخىي ئابىدىسىدۇر.","jingfu sariyi koréyening muhim tarixiy abidisidur."]],"书信集":[["这本书信集收录了名家作品。","بۇ خەتلەر توپلىمى مەشھۇر ئەدىبلەرنىڭ ئەسەرلىرىنى ئۆز ئىچىگە ئالىدۇ.","bu xetler toplimi meshhur ediblerning eserlirini öz ichige alidu."]],"暴食":[["他经常有暴食的坏习惯。","ئۇنىڭ دائىم ئوچۇق يېيىش دېگەن يامان ئادىتى بار.","uning daim ochuq yéyish dégen yaman aditi bar."]],"曼海姆":[["曼海姆是德国西南部的一座城市。","مانھېيم گېرمانىيەنىڭ غەربىي جەنۇبىدىكى بىر شەھەر.","manhéym gérmaniyening gherbiy jenubidiki bir sheher."]],"更生":[["万物更生，充满无限生机。","ھەممە نەرسە يېڭىدىن جانلىنىپ، چەكسىز ھاياتىي كۈچكە تولدى.","hemme nerse yéngidin janlinip, cheksiz hayatiy küchke toldi."]],"服务生":[["服务生端上了美味的菜肴。","مۇلازىمەتچى لەززەتلىك تائاملارنى ئېلىپ كەلدى.","mulazimetchi lezzetlik taamlarni élip keldi."]],"朝雨":[["朝雨滋润着清晨的田野。","تەڭرىتاغ ئېتىزلىرىنى ئەتىگەن يامغۇرى سۇغىرىۋاتىدۇ.","tengritagh étizlirini etigen yamghuri sughiriwatidu."]],"朝门":[["朝门是官员上朝的入口。","ئوردا دەرۋازىسى ئەمەلدارلارنىڭ ئوردىغا كىرىش ئېغىزىدۇر.","orda derwazisi emeldarlarning ordigha kirish éghizidur."]],"末茶":[["末茶是最后泡的一杯茶。","ئاخىرقى چاي ئەڭ ئاخىرىدا دەملەنگەن بىر چىنە چاي.","axirqi chay eng axirida demlengen bir chine chay."]],"末叶":[["末叶已经逐渐变黄了。","ئاخىرقى يوپۇرماق ئاستا-ئاستا سېرىقىيىپ كەتتى.","axirqi yopurmaq asta-asta sériqiyip ketti."]],"本底调查":[["本底调查有助于了解环境状况。","ئاساسىي تەكشۈرۈش مۇھىت ئەھۋالىنى چۈشىنىشكە ياردەم بېرىدۇ.","asasiy tekshürüsh muhit ehwalini chüshinishke yardem béridu."]],"杏花岭":[["杏花岭是北京的著名景点。","ئۆرۈك گۈل تېغى بېيجىڭنىڭ مەشھۇر مەنزىرىسىدۇر.","örük gül téghi béyjingning meshhur menzirisidur."]],"杜宇":[["杜宇是古代的神话人物。","دۇيۈ قەدىمكى زاماندىكى ئەپسانىۋى شەخستۇر.","duyü qedimki zamandiki epsaniwi shexstur."]],"本土派":[["本土派艺术家擅长融合传统与现代元素。","يەرلىك ئېقىم سەنئەتكارلىرى ئەنئەنە بىلەن زامانىۋى ئېلېمېنتلارنى بىرلەشتۈرۈشكە ماھىر.","yerlik éqim sen'etkarliri en'ene bilen zamaniwi éléméntlarni birleshtürüshke mahir."]],"本字":[["本字在书法中具有重要地位。","بېنزى خەتتاتلىقتا مۇھىم ئورۇنغا ئىگە.","bénzi xettatliqta muhim orungha ige."]],"杜鹃啼血":[["杜鹃啼血常用来形容悲鸣。","دۇجۈەننىڭ قان يىغلىشى ئادەتتە مۇڭلۇق سايراشنى تەسۋىرلەشكە ئىشلىتىلىدۇ.","dujüenning qan yighlishi adette mungluq sayrashni teswirleshke ishlitilidu."]],"松岭区":[["松岭区以自然风光著称。","سۇڭلىڭ رايونى تەبىئىي مەنزىرىسى بىلەن داڭلىق.","sungling rayoni tebiiy menzirisi bilen dangliq."]],"林园乡":[["林园乡以种植水果而闻名。","لىنيۈەن يېزىسى مېۋە ئۆستۈرۈش بىلەن تونۇلغان.","linyüen yézisi méwe östürüsh bilen tonulghan."]],"林夜鹰":[["林夜鹰在月光下展开宽大的翅膀。","لىن يېچىيىڭ ئاي نۇرى ئاستىدا كەڭ قاناتلىرىنى يازىدۇ.","lin yéchiying ay nuri astida keng qanatlirini yazidu."]],"果蝇":[["果蝇在实验室中常被用作实验对象。","مېۋە چىۋىنى لابوراتورىيەدە ئادەتتە تەجرىبە ئوبيېكتى سۈپىتىدە ئىشلىتىلىدۇ.","méwe chiwini laboratoriyede adette tejribe obyékti süpitide ishlitilidu."]],"东丰县":[["东丰县以优质大米闻名。","دۇڭفېڭ ناھىيىسى يۇقىرى سۈپەتلىك گۈرۈچ بىلەن داڭلىق.","dungféng nahiyisi yuqiri süpetlik gürüch bilen dangliq."]],"柏辽兹":[["柏辽兹是19世纪的法国作曲家。","بېرلىيوز 19-ئەسىردىكى فرانسىيە كومپوزىتورى.","bérliyoz 19-esirdiki fransiye kompozitori."]],"架次":[["飞机每天有多架次航班。","ئايروپىلاننىڭ ھەر كۈنى بىر قانچە قېتىملىق نۆۋىتى بار.","ayropilanning her küni bir qanche qétimliq nöwiti bar."]],"校运会":[["校运会丰富了学生的课余生活。","مەكتەپ تەنتەربىيە يىغىنى ئوقۇغۇچىلارنىڭ دەرستىن سىرتقى تۇرمۇشىنى بېيىتتى.","mektep tenterbiye yighini oqughuchilarning derstin sirtqi turmushini béyitti."]],"栅子":[["栅栏的另一种说法是栅子。","قاشىقنىڭ يەنە بىر ئاتىلىشى چىت.","qashiqning yene bir atilishi chit."]],"栓塞":[["血管栓塞会导致血液循环障碍。","قان تومۇر تىقىلىشى قان ئايلىنىشىغا توسالغۇ پەيدا قىلىدۇ.","qan tomur tiqilishi qan aylinishigha tosalghu peyda qilidu."]],"核能源":[["核能源正在被广泛开发利用。","يادرو ئېنېرگىيەسى كەڭ دائىرىدە ئېچىلىپ پايدىلىنىلماقتا.","yadro énérgiyesi keng dairide échilip paydilinilmaqta."]],"核推进":[["核推进可用于深空探测任务。","يادرو ئىتتىرىش چوڭقۇر ئالەم تەكشۈرۈش ۋەزىپىلىرىدە قوللىنىلىشى مۇمكىن.","yadro ittirish chongqur alem tekshürüsh wezipiliride qollinilishi mumkin."]],"柳条边":[["柳条边是古代用于防御的边界设施，由柳树枝条构成。","ليۇتياۋبىەن قەدىمكى زاماندا مۇداپىئە ئۈچۈن ئىشلىتىلگەن چېگرا ئەسلىھەسى بولۇپ، سۆگەت شاخلىرىدىن ياسالغان.","lyutyawbien qedimki zamanda mudapie üchün ishlitilgen chégra eslihesi bolup, söget shaxliridin yasalghan."]],"梅子":[["梅子成熟后可以用来制作果酱。","Meizi پىشقاندىن كېيىن مۇراببا ياساشقا ئىشلىتىلىدۇ.","Meizi pishqandin kéyin murabba yasashqa ishlitilidu."]],"梯氏鸫":[["梯氏鸫是一种分布于亚洲的鸟类。","تروتسكىي تۇردى ئاسىيادا تارقالغان بىر خىل قۇشتۇر.","trotskiy turdi asiyada tarqalghan bir xil qushtur."]],"棕榈属":[["棕榈属包含许多不同种类的植物。","پالمىلار ئائىلىسىگە تۈرلۈك ئوخشىمىغان ئۆسۈملۈك تۈرلىرى كىرىدۇ.","palmilar ailisige türlük oxshimighan ösümlük türliri kiridu."]],"棕榈襞":[["棕榈襞是棕榈叶上的特殊褶皱结构。","پالم قاتلىمى پالم يوپۇرمىقىدىكى ئالاھىدە بۈكلەش قۇرۇلمىسىدۇر.","palm qatlimi palm yopurmiqidiki alahide büklesh qurulmisidur."]],"棒国":[["棒国的文化在亚洲有着深远的影响。","كورىيەنىڭ مەدەنىيىتى ئاسىيادا چوڭقۇر تەسىرگە ئىگە.","koriyening medeniyiti asiyada chongqur tesirge ige."]],"棕腹杜鹃":[["棕腹杜鹃常寄生在鸟巢中。","قوڭۇر قورساقلىق كاككۇك قۇشى كۆپىنچە قۇش ئۇۋىسىغا پارازىتلىق ياشايدۇ.","qongur qorsaqliq kakkuk qushi köpinche qush uwisigha parazitliq yashaydu."]],"棕腹柳莺":[["棕腹柳莺的歌声婉转悠扬。","قوڭۇر قورساقلىق تال چىمپىقىنىڭ ناخشىسى ئەگرى-توقاي ھەم سۈزۈك.","qongur qorsaqliq tal chimpiqining naxshisi egri-toqay hem süzük."]],"枫叶":[["枫叶是枫树的叶子，形状独特，色彩鲜艳。","فېڭ يوپۇرماقى فېڭ دەرىخىنىڭ يوپۇرماقى بولۇپ، شەكلى ئالاھىدە، رەڭگى پارقىراق.","féng yopurmaqi féng derixining yopurmaqi bolup, shekli alahide, renggi parqiraq."]],"楔尾绿鸠":[["楔尾绿鸠是一种羽毛呈绿色的鸽子。","پانا قۇيرۇقلۇق يېشىل پەيخۇ قۇشنىڭ پەيلىرى يېشىل رەڭدە بولىدۇ.","pana quyruqluq yéshil peyxu qushning peyliri yéshil rengde bolidu."]],"乐活":[["乐活是一种健康的生活方式。","لېخۇو بىر ساغلام تۇرمۇش ئۇسۇلى.","léxuo bir saghlam turmush usuli."]],"楼座":[["楼座的设计很独特。","بىنا ئورۇنلاشتۇرۇشى بەك ئالاھىدە.","bina orunlashturushi bek alahide."]],"桦树":[["桦树适应性强，分布广泛。","خۇا دەرىخى ماسلىشىشچانلىقى كۈچلۈك، تارقىلىشى كەڭ.","xua derixi maslishishchanliqi küchlük, tarqilishi keng."]],"桥台":[["桥台连接桥梁与地面。","كۆۋرۈك ئاساسى كۆۋرۈكنى يەر بىلەن تۇتاشتۇرىدۇ.","köwrük asasi köwrükni yer bilen tutashturidu."]],"枪法":[["他的枪法在团队中数一数二。","ئۇنىڭ ئوق ئېتىش ماھارىتى كوماندىدا بىرىنچى-ئىككىنچى ئورۇندا.","uning oq étish mahariti komandida birinchi-ikkinchi orunda."]],"机械工人":[["机械工人操作重型机械。","مېخانىك ئىشچىلار ئېغىر مېخانىكىلىق ئۈسكۈنىلەرنى باشقۇرىدۇ.","méxanik ishchilar éghir méxanikiliq üskünilerni bashquridu."]],"欲绝":[["他几乎欲绝，无法呼吸。","ئۇ ھەيرانلىقتىن ھاڭۋاقىپ، نەپەس ئالالماي قالدى.","u heyranliqtin hangwaqip, nepes alalmay qaldi."]],"欧若拉":[["欧若拉是北极光的别称。","ئاۋرورا شىمالىي قۇتۇپ نۇرىنىڭ باشقا ئاتىلىشىدۇر.","awrora shimaliy qutup nurining bashqa atilishidur."]],"歌德":[["歌德是德国著名的文学家。","گېتې گېرمانىيەنىڭ مەشھۇر ئەدىبى.","gété gérmaniyening meshhur edibi."]],"次第":[["他按照次第完成了所有任务。","ئۇ بارلىق ۋەزىپىلەرنى تەرتىپ بويىچە ئورۇندىدى.","u barliq wezipilerni tertip boyiche orundidi."]],"欲加之罪，何患无辞":[["欲加之罪，何患无辞。","ئەيىب تاپماقچى بولساڭ، باھانە تاپىسەن.","eyib tapmaqchi bolsang, bahane tapisen."]],"武强县":[["武强县位于河北省南部。","ۋۇچياڭ ناھىيىسى خېبېي ئۆلكىسىنىڭ جەنۇبىدا جايلاشقان.","wuchyang nahiyisi xébéy ölkisining jenubida jaylashqan."]],"死心眼儿":[["他真是个死心眼儿的人。","ئۇ ھەقىقەتەن قاتتىق كۆڭۈل ئادەم.","u heqiqeten qattiq köngül adem."]],"死文字":[["这些死文字难以理解。","بۇ ئۆلۈك يېزىقلارنى چۈشىنىش قىيىن.","bu ölük yéziqlarni chüshinish qiyin."]],"死灰复燃":[["旧事重提，死灰复燃。","كونا ئىشنى قايتا تىلغا ئېلىش، ئۆلۈك كۈلنى قايتا ياندۇرۇش.","kona ishni qayta tilgha élish, ölük külni qayta yandurush."]],"历史博物馆":[["历史博物馆收藏着丰富的文物珍品。","تارىخ مۇزېيى مول مەدەنىي يادىكارلىق گۆھەرلىرىنى ساقلايدۇ.","tarix muzéyi mol medeniy yadikarliq göherlirini saqlaydu."]],"母题":[["母题是故事创作的核心主题。","ئانا تېما ھېكايە ئىجادىيىتىنىڭ يادرولۇق تېمىسىدۇر.","ana téma hékaye ijadiyitining yadroluq témisidur."]],"每年一度":[["每年一度的马拉松比赛备受期待。","ھەر يىلى ئۆتكۈزۈلىدىغان مارافون مۇسابىقىسى كۆپ ئۈمىد بىلەن كۈتۈلىدۇ.","her yili ötküzülidighan marafon musabiqisi köp ümid bilen kütülidu."]],"比湿":[["他们比湿度的大小。","ئۇلار نەملىك دەرىجىسىنىڭ چوڭ-كىچىكلىكىنى سېلىشتۇرىدۇ.","ular nemlik derijisining chong-kichiklikini sélishturidu."]],"民建联":[["民建联是重要的政治组织。","خەلق قۇرۇلۇش بىرلەشمىسى مۇھىم سىياسىي تەشكىلات.","xelq qurulush birleshmisi muhim siyasiy teshkilat."]],"殒命":[["他在事故中不幸殒命。","ئۇ ھادىسىدە بەختسىزلىكتىن ھاياتىدىن ئايرىلدى.","u hadiside bextsizliktin hayatidin ayrildi."]],"殡葬":[["殡葬服务非常专业。","دەپنە مۇلازىمىتى بەك كەسپىي ئىدى.","depne mulazimiti bek kespiy idi."]],"段错误":[["程序出现段错误需要修复。","پروگراممىدا بۆلەك خاتالىقى كۆرۈلدى، تۈزىتىش كېرەك.","programmida bölek xataliqi körüldi, tüzitish kérek."]],"氧割":[["氧割技术能迅速切割厚金属板。","ئوكسىگېن كېسىش تېخنىكىسى قېلىن مېتال تاختىلارنى تېز كېسەلەيدۇ.","oksigén késish téxnikisi qélin métal taxtilarni téz késeleydu."]],"水烟":[["水烟是一种传统的吸烟方式。","سۇ چىلىمى ئەنئەنىۋى تاماكا چېكىش ئۇسۇلىدۇر.","su chilimi en'eniwi tamaka chékish usulidur."]],"水烟壶":[["水烟壶用来过滤吸入的烟雾。","سۇ چىلىمى چۆگىنى تارتىلغان تۈتۈننى سۈزۈش ئۈچۈن ئىشلىتىلىدۇ.","su chilimi chögini tartilghan tütünni süzüsh üchün ishlitilidu."]],"永和县":[["永和县历史悠久。","يۇڭخې ناھىيىسىنىڭ تارىخى ئۇزۇن.","yungxé nahiyisining tarixi uzun."]],"水星":[["水星是离太阳最近的行星。","مېركۇرىي قۇياشقا ئەڭ يېقىن پلانېتا.","mérkuriy quyashqa eng yéqin planéta."]],"水生":[["水生植物需要湿润环境。","سۇدا ئۆسىدىغان ئۆسۈملۈكلەر نەم ھاۋالىق مۇھىتقا ئېھتىياجلىق.","suda ösidighan ösümlükler nem hawaliq muhitqa éhtiyajliq."]],"水力发电":[["水力发电是利用水流能量产生电力的方式。","سۇ كۈچى بىلەن ئېلېكتر ئىشلەپچىقىرىش سۇ ئېقىمىنىڭ ئېنېرگىيەسىدىن پايدىلىنىپ ئېلېكتر ئىشلەپچىقىرىش ئۇسۇلى.","su küchi bilen éléktr ishlepchiqirish su éqimining énérgiyesidin paydilinip éléktr ishlepchiqirish usuli."]],"永昌县":[["永昌县出产优质的农产品。","يۇڭچاڭ ناھىيىسى ئەلا سۈپەتلىك يېزا ئىگىلىك مەھسۇلاتلىرى ئىشلەپچىقىرىدۇ.","yungchang nahiyisi ela süpetlik yéza igilik mehsulatliri ishlepchiqiridu."]],"汶上县":[["汶上县位于山东省中部。","ۋېنشاڭ ناھىيىسى شەندۇڭ ئۆلكىسىنىڭ مەركىزىدە جايلاشقان.","wénshang nahiyisi shendung ölkisining merkizide jaylashqan."]],"江猪":[["江猪是生活在山区的一种野生动物。","جياڭجۇ تاغلىق رايوندا ياشايدىغان بىر خىل ياۋايى ھايۋان.","jyangju taghliq rayonda yashaydighan bir xil yawayi haywan."]],"没法儿":[["他真没法儿了。","ئۇنىڭ ھەقىقەتەن ئامالى قالمىدى.","uning heqiqeten amali qalmidi."]],"沿河县":[["沿河县位于山区。","دەريا بويى ناھىيىسى تاغلىق رايوندا جايلاشقان.","derya boyi nahiyisi taghliq rayonda jaylashqan."]],"泄殖肛孔":[["这种动物只有一个泄殖肛孔。","بۇ خىل ھايۋاننىڭ پەقەت بىرلا مەخرەج-مەقئەد تۆشۈكى بار.","bu xil haywanning peqet birla mexrej-meq'ed töshüki bar."]],"求购":[["我想求购一台二手自行车。","مەن ئىككىنچى قول ۋېلىسىپىت سېتىۋالماقچى.","men ikkinchi qol wélisipit sétiwalmaqchi."]],"波斯尼亚":[["波斯尼亚是巴尔干半岛的国家。","بوسنىيە بالقان يېرىم ئارىلىدىكى دۆلەت.","bosniye balqan yérim arilidiki dölet."]],"泰武乡":[["泰武乡保留着许多传统习俗。","تەيۋۇ يېزىسى نۇرغۇن ئەنئەنىۋى ئادەتلەرنى ساقلاپ قالغان.","teywu yézisi nurghun en'eniwi adetlerni saqlap qalghan."]],"洛浦":[["洛浦公园是西安的著名景点。","لوپۇ باغچىسى شيەننىڭ مەشھۇر مەنزىرىلىك جايىدۇر.","lopu baghchisi shyenning meshhur menzirilik jayidur."]],"洗衣店":[["这家洗衣店服务很好。","بۇ كىيىم يۇيۇش دۇكىنىنىڭ مۇلازىمىتى ئىنتايىن ياخشى.","bu kiyim yuyush dukinining mulazimiti intayin yaxshi."]],"洗面":[["洗面可以保持清洁。","يۈز يۇيۇش تازالىقنى ساقلايدۇ.","yüz yuyush tazaliqni saqlaydu."]],"浠水县":[["浠水县是黄冈市下辖县。","شىشۇي ناھىيىسى خۇاڭگاڭ شەھىرىگە قاراشلىق ناھىيەدۇر.","shishuy nahiyisi xuanggang shehirige qarashliq nahiyedur."]],"活分":[["活分取决于个人的努力与态度。","ئەمەلىي كۈچ شەخسنىڭ تىرىشچانلىقى ۋە پوزىتسىيىسىگە باغلىق.","emeliy küch shexsning tirishchanliqi we pozitsiyisige baghliq."]],"流理台":[["厨房的流理台非常干净。","ئاشخانىنىڭ ئاقار ئۈستەل تاختىسى ئىنتايىن تازا.","ashxanining aqar üstel taxtisi intayin taza."]],"海城市":[["海城市以海鲜闻名。","ھەيچېڭ شەھىرى دېڭىز مەھسۇلاتلىرى بىلەن داڭلىق.","heychéng shehiri déngiz mehsulatliri bilen dangliq."]],"海涂":[["海涂经过围垦成为农田。","دېڭىز سايلىقى قورشاپ تېرىلغۇ يەرگە ئايلاندى.","déngiz sayliqi qorshap térilghu yerge aylandi."]],"海外华人":[["海外华人保持中国文化。","چەتئەلدىكى جۇڭگولۇقلار جۇڭگو مەدەنىيىتىنى ساقلايدۇ.","chet'eldiki junggoluqlar junggo medeniyitini saqlaydu."]],"海外赤子":[["海外赤子心系祖国。","چەتئەلدىكى ۋەتەنپەرۋەر پەرزەنتلەر ۋەتەن بىلەن يۈرەك باغلايدۇ.","chet'eldiki wetenperwer perzentler weten bilen yürek baghlaydu."]],"海王星":[["海王星是太阳系行星。","نېپتۇن قۇياش سىستېمىسىدىكى بىر پلانېتادۇر.","néptun quyash sistémisidiki bir planétadur."]],"海瓜子":[["海瓜子是沿海的特产。","دېڭىز قاپاقچىسى دېڭىز بويىنىڭ ئالاھىدە مەھسۇلاتىدۇر.","déngiz qapaqchisi déngiz boyining alahide mehsulatidur."]],"涉笔":[["他涉笔多年，文笔流畅。","ئۇ كۆپ يىللاردىن بېرى يېزىش بىلەن شۇغۇللىنىپ، ئەسەرلىرى راۋان.","u köp yillardin béri yézish bilen shughullinip, eserliri rawan."]],"海陆空":[["海陆空运输都很发达。","دېڭىز، قۇرۇقلۇق ۋە ھاۋا توشۇشى ناھايىتى تەرەققىي قىلغان.","déngiz, quruqluq we hawa toshushi nahayiti tereqqiy qilghan."]],"淆乱":[["这些文件内容十分淆乱。","بۇ ھۆججەتلەرنىڭ مەزمۇنى ئىنتايىن قالايمىقان.","bu höjjetlerning mezmuni intayin qalaymiqan."]],"泪痕":[["脸上还留着泪痕。","يۈزىدە يەنىلا ياش ئىزلىرى بار.","yüzide yenila yash izliri bar."]],"港人":[["港人普遍使用粤语交流。","شياڭگاڭلىقلار ئومۇمەن كانتون تىلىدا سۆزلىشىدۇ.","shyanggangliqlar omumen kanton tilida sözlishidu."]],"港区":[["港区是城市的经济中心。","پورت رايونى شەھەرنىڭ ئىقتىساد مەركىزى.","port rayoni sheherning iqtisad merkizi."]],"减压症":[["他出现了减压症症状。","ئۇنىڭدا بېسىم ئازايتىش كېسەللىك ئالامەتلىرى كۆرۈلدى.","uningda bésim azaytish késellik alametliri körüldi."]],"溶没":[["岩石经过长时间被水流溶没。","تاشلار ئۇزۇن ۋاقىت سۇ ئېقىمى تەرىپىدىن ئېرىتىلىپ يوقىتىلىدۇ.","tashlar uzun waqit su éqimi teripidin éritilip yoqitilidu."]],"滑溜":[["地面太滑溜，容易摔倒。","يەر بەك تېيىلغاق، يىقىلىپ كېتىش ئاسان.","yer bek téyilghaq, yiqilip kétish asan."]],"滑膜":[["滑膜在关节中起到润滑作用。","سىنوۋىيال پەردە بوغۇم ئىچىدە مايلىغۇچ رولىنى ئوينايدۇ.","sinowiyal perde boghum ichide maylighuch rolini oynaydu."]],"滕王阁":[["滕王阁是南昌的著名景点。","تېڭۋاڭ سارىيى نەنچاڭنىڭ مەشھۇر مەنزىرىسىدۇر.","téngwang sariyi nenchangning meshhur menzirisidur."]],"温度表":[["温度表显示室温为25摄氏度。","تېمپېراتۇرا ئۆلچىگۈچ ئۆي تېمپېراتۇرىسىنىڭ 25 سېلسىيە گرادۇس ئىكەنلىكىنى كۆرسەتتى.","témpératura ölchigüch öy témpératurisining 25 sélsiye gradus ikenlikini körsetti."]],"汉腔":[["汉腔是一种传统的戏曲唱腔。","خەنچياڭ ئەنئەنىۋى بىر تىياتىر ئاھاڭىدۇر.","xenchyang en'eniwi bir tiyatir ahangidur."]],"润滑":[["机器需要定期润滑。","ماشىنا مۇنتىزىم ياغلىنىشقا موھتاج.","mashina muntizim yaghlinishqa mohtaj."]],"满公":[["满公是古代的一个官职。","مانجۇڭگو بۇ قەدىمكى زاماندىكى بىر ئەمەلدار ئىدى.","manjunggo bu qedimki zamandiki bir emeldar idi."]],"滤毒通风装置":[["滤毒通风装置能过滤有毒气体。","زەھەر سۈزگۈچ ھاۋا ئالماشتۇرۇش ئۈسكۈنىسى زەھەرلىك گازلارنى سۈزەلەيدۇ.","zeher süzgüch hawa almashturush üskünisi zeherlik gazlarni süzeleydu."]],"滩头":[["部队在滩头构筑了坚固的防御工事。","قىسىم قىرغاق بېشىدا مۇستەھكەم مۇداپىئە ئىستىھكامى قۇردى.","qisim qirghaq béshida mustehkem mudapie istihkami qurdi."]],"灰冠鹟莺":[["灰冠鹟莺在枝头鸣唱。","كۈلرەڭ تاجلىق چىمچىقى شاختاردا سايرايدۇ.","külreng tajliq chimchiqi shaxtarda sayraydu."]],"火并":[["两派势力发生激烈火并。","ئىككى تەرەپ كۈچلىرى ئوتتۇرىسىدا كەسكىن ئوت ئېچىش يۈز بەردى.","ikki terep küchliri otturisida keskin ot échish yüz berdi."]],"灰脸𫛭鹰":[["灰脸𫛭鹰在空中盘旋捕猎。","كۈمۈشسىمان يۈزلۈك بۈركۈت ھاۋادا ئايلىنىپ ئولجا تۇتىدۇ.","kümüshsiman yüzlük bürküt hawada aylinip olja tutidu."]],"灰头柳莺":[["灰头柳莺在枝头跳跃。","كۈمۈشسىمان باش تال چىمچىقى شاخ ئۈستىدە سەكرەيدۇ.","kümüshsiman bash tal chimchiqi shax üstide sekreydu."]],"为啥":[["为啥他这么生气？","نېمە ئۈچۈن ئۇ بۇنچە ئاچچىقلاندى؟","néme üchün u bunche achchiqlandi?"]],"烈女":[["烈女的故事激励着后人。","مەرد ئاياللارنىڭ ھېكايىسى كېيىنكىلەرنى ئىلھاملاندۇرىدۇ.","merd ayallarning hékayisi kéyinkilerni ilhamlanduridu."]],"无形中":[["他在无形中帮助了他人。","ئۇ شەكىلسىز ھالدا باشقىلارغا ياردەم قىلدى.","u shekilsiz halda bashqilargha yardem qildi."]],"无业闲散":[["他整天无业闲散，无所事事。","ئۇ كۈن بويى ئىشسىز تەنھەرىكەت قىلىپ، ھېچ ئىش قىلمايدۇ.","u kün boyi ishsiz tenheriket qilip, héch ish qilmaydu."]],"煲电话粥":[["他们煲电话粥到很晚。","ئۇلار كېچىگە قەدەر تېلېفوندا ئۇزۇن سۆزلەشتى.","ular kéchige qeder téléfonda uzun sözleshti."]],"熄灯":[["熄灯后，整个房间一片漆黑。","چىراغ ئۆچۈرۈلگەندىن كېيىن، پۈتۈن ئۆي قاراڭغۇلۇققا چۆمدى.","chiragh öchürülgendin kéyin, pütün öy qarangghuluqqa chömdi."]],"熟道儿":[["这条熟道儿，我从小就走。","بۇ پىششىق يولنى مەن كىچىكىمدىن ماڭىمەن.","bu pishshiq yolni men kichikimdin mangimen."]],"烟枪":[["烟枪是吸食鸦片的主要工具。","تاماكا چىلىمى ئەپيۇن چېكىشنىڭ ئاساسلىق قورالى.","tamaka chilimi epyun chékishning asasliq qorali."]],"焙烤":[["焙烤常用于制作面包或饼干。","بېيكاۋ ئادەتتە بولكا ياكى پېچېنە ياساشتا ئىشلىتىلىدۇ.","béykaw adette bolka yaki péchéne yasashta ishlitilidu."]],"焚尸炉":[["焚尸炉用于将尸体火化。","مېيىت كۆيدۈرۈش ئوچىقى مېيىتنى ئوتقا ياقىشقا ئىشلىتىلىدۇ.","méyit köydürüsh ochiqi méyitni otqa yaqishqa ishlitilidu."]],"无花果":[["无花果是常见的水果之一。","ئەنجۈر كۆپ ئۇچرايدىغان مېۋىلەرنىڭ بىرى.","enjür köp uchraydighan méwilerning biri."]],"牌价":[["今天的牌价上涨了不少。","بۈگۈنكى باھا خېلى كۆپ ئۆستى.","bügünki baha xéli köp östi."]],"牌号":[["这家店的牌号很有名。","بۇ دۇكاننىڭ تاختاي نومۇرى ناھايىتى مەشھۇر.","bu dukanning taxtay nomuri nahayiti meshhur."]],"争取时间":[["他努力争取时间，赶在截止日期前完成。","ئۇ ۋاقىتنى تالىشىپ، ئاخىرقى مۇددەتتىن بۇرۇن تاماملىدى.","u waqitni taliship, axirqi muddettin burun tamamlidi."]],"特种部队":[["特种部队擅长突袭作战。","ئالاھىدە قىسىملار تۇيۇقسىز ھۇجۇم قىلىش جەڭگىدە ماھىر.","alahide qisimlar tuyuqsiz hujum qilish jenggide mahir."]],"犯罪学":[["犯罪学是一门研究犯罪现象的学科。","جىنايەتشۇناسلىق جىنايەت ھادىسىسىنى تەتقىق قىلىدىغان پەن.","jinayetshunasliq jinayet hadisisini tetqiq qilidighan pen."]],"猎豹":[["猎豹是速度最快的猫科动物。","ئوۋ قاپلانى ئەڭ تېز مۈشۈك ئائىلىسىدىكى ھايۋان.","ow qaplani eng téz müshük ailisidiki haywan."]],"王化":[["王化在科技领域颇有建树。","ۋاڭ خۇا پەن-تېخنىكا ساھەسىدە كۆرۈنەرلىك نەتىجىلەرگە ئېرىشكەن.","wang xua pen-téxnika saheside körünerlik netijilerge érishken."]],"玩伴":[["他们是从小一起长大的玩伴。","ئۇلار كىچىكىدىن بىللە ئۆسكەن ئوينايدىغان ھەمراھلار.","ular kichikidin bille ösken oynaydighan hemrahlar."]],"玩儿得转":[["她非常懂得如何玩儿得转各种社交场合。","ئۇ ھەر خىل ئىجتىمائىي مەيدانلاردا قانداق ئويناپ مۇۋەپپەقىيەت قازىنىشنى ناھايىتى ياخشى بىلىدۇ.","u her xil ijtimaiy meydanlarda qandaq oynap muweppeqiyet qazinishni nahayiti yaxshi bilidu."]],"玩兴":[["他的玩兴被彻底激发。","ئۇنىڭ ئويناش ئىشتىيىقى پۈتۈنلەي قوزغىتىلدى.","uning oynash ishtiyiqi pütünley qozghitildi."]],"琐闻":[["这些琐闻常常出现在报纸上。","بۇ ئۇششاق خەۋەرلەر كۆپىنچە گېزىتلەردە كۆرۈلىدۇ.","bu ushshaq xewerler köpinche gézitlerde körülidu."]],"玻璃体":[["玻璃体是眼球的重要组成部分。","فىتورېس كۆزنىڭ مۇھىم تەركىبىي قىسمىدۇر.","fitorés közning muhim terkibiy qismidur."]],"田赛":[["田赛是田径比赛中的重要项目。","دېڭىز مۇسابىقىسى يېنىڭ ئېتىلىش مۇسابىقىسىدىكى مۇھىم تۈر.","déngiz musabiqisi yéning étilish musabiqisidiki muhim tür."]],"甲肝":[["甲肝主要通过粪口传播。","جيا گان يۇقۇمى ئاساسلىقى نەجەس-ئېغىز يولى ئارقىلىق تارقىلىدۇ.","jya gan yuqumi asasliqi nejes-éghiz yoli arqiliq tarqilidu."]],"留得青山在，不怕没柴烧":[["只要留得青山在，不怕没柴烧。","تاغ-دەرەخ بولسىلا، ئوتۇن يوق دەپ قورقمىغىن.","tagh-derex bolsila, otun yoq dep qorqmighin."]],"产前检查":[["产前检查确保母婴安全。","تۇغۇتتىن بۇرۇنقى تەكشۈرۈش ئانا ۋە بالىنىڭ بىخەتەرلىكىنى كاپالەتكە ئىگە قىلىدۇ.","tughuttin burunqi tekshürüsh ana we balining bixeterlikini kapaletke ige qilidu."]],"画框":[["精美的画框能让整幅画作更具观赏性。","نەپىس رامكا پۈتۈن رەسىمنى تېخىمۇ كۆرۈنەرلىك قىلالايدۇ.","nepis ramka pütün resimni téximu körünerlik qilalaydu."]],"异面直线":[["异面直线在空间中不相交。","ئوخشاش بولمىغان تەكشىلىكتىكى تۈز سىزىقلار بوشلۇقتا كېسىشمەيدۇ.","oxshash bolmighan tekshiliktiki tüz siziqlar boshluqta késishmeydu."]],"发奋有为":[["年轻人发奋有为，成就非凡。","ياشلار تىرىشىپ ئىشلەپ، كۆزگە كۆرۈنەرلىك نەتىجىلەرگە ئېرىشتى.","yashlar tiriship ishlep, közge körünerlik netijilerge érishti."]],"百物":[["这里的百物琳琅满目，让人眼花缭乱。","بۇ يەردىكى يۈز خىل نەرسە كۆزنى قاماشتۇرىدۇ.","bu yerdiki yüz xil nerse közni qamashturidu."]],"磷脂":[["磷脂是细胞膜的重要组成部分。","فوسفولىپىد ھۈجەيرە پەردىسىنىڭ مۇھىم تەركىبىي قىسمى.","fosfolipid hüjeyre perdisining muhim terkibiy qismi."]],"短距离":[["短距离飞行需要技术。","قىسقا ئارىلىقتا ئۇچۇش تېخنىكا تەلەپ قىلىدۇ.","qisqa ariliqta uchush téxnika telep qilidu."]],"石松":[["石松是一种适应岩石环境的植物。","شىسۇڭ تاش مۇھىتىغا ماسلاشقان ئۆسۈملۈك.","shisung tash muhitigha maslashqan ösümlük."]],"矿床":[["大型矿床的发现推动了当地经济发展。","چوڭ كان ئورۇنلىرىنىڭ بايقىلىشى يەرلىك ئىقتىسادنىڭ تەرەققىياتىنى ئىلگىرى سۈردى.","chong kan orunlirining bayqilishi yerlik iqtisadning tereqqiyatini ilgiri sürdi."]],"社头乡":[["社头乡风景优美。","ئىجتىمائىي باشلىق يېزىسىنىڭ مەنزىرىسى گۈزەل.","ijtimaiy bashliq yézisining menzirisi güzel."]],"纱笼":[["她穿着纱笼跳舞。","ئۇ داكا كۆينەك كىيىپ ئۇسسۇل ئوينىدى.","u daka köynek kiyip ussul oynidi."]],"绍兴酒":[["绍兴酒是一种历史悠久的黄酒。","شاۋشىڭ ھارىقى ئۇزۇن تارىخقا ئىگە سېرىق ھاراق.","shawshing hariqi uzun tarixqa ige sériq haraq."]],"紫金山":[["紫金山是南京著名的景点。","جىڭجىن تېغى نەنجىڭنىڭ مەشھۇر مەنزىرىسىدۇر.","jingjin téghi nenjingning meshhur menzirisidur."]],"结连":[["他们结连合作，共同创业。","ئۇلار بىرلىشىپ ھەمكارلىشىپ، بىرلىكتە ئىش باشلىدى.","ular birliship hemkarliship, birlikte ish bashlidi."]]};
